INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('df1b4e0f-3261-4c70-b309-b07cedae7e84', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'A 30-year-old male patient with non-valvular atrial fibrillation has a CHA2DS2-VASc score of 4 and an ORBIT score of 3. Renal function reveals a CrCl of 42 mL/min. (Case Ref: CARDIOVASCULAR-0030). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate anticoagulation strategy according to NICE NG196?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('86da6529-080b-4c13-9a0e-27917731d6a5', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'A', 'Apixaban 5 mg twice daily (or standard DOAC dose adjusted for renal function)', 1, 'Correct. A Direct-acting Oral Anticoagulant (DOAC) is first-line over warfarin for non-valvular AF. For apixaban, dose reduction to 2.5 mg bd is only triggered if 2 of 3 criteria apply: age >= 80, weight <= 60kg, serum creatinine >= 133 mcmol/L.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c130819c-22cd-43ce-894f-6a29a2ce4d25', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'B', 'Warfarin with target INR 2.0 to 3.0', 0, 'Sub-optimal. DOACs demonstrate superior or non-inferior safety and efficacy with lower intracranial haemorrhage rates compared to warfarin.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('27867950-fc78-4cf8-a6c2-45949178c90f', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'C', 'Aspirin 75 mg daily monotherapy', 0, 'Contraindicated. Aspirin monotherapy is explicitly contraindicated for stroke prevention in AF because it provides negligible stroke reduction while increasing major bleeding.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9e2d5322-0df8-4ba4-aa06-3c1712235a41', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bdf0d36e-48e3-4f86-9743-a21961effcb1', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('0f7810db-0159-40cf-9f62-bf26a1b80fc2', '2a0ca1b8-958f-468c-a563-75f2a526b227', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('88f8ac79-8d83-49c1-96d9-b28815b0e491', '2a0ca1b8-958f-468c-a563-75f2a526b227', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
