INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5c6c7919-8c29-4959-a007-3e62dcc08fd0', '21e254ec-eec6-46ab-8ba1-de4560358d37', 'C', 'Bisoprolol 5 mg orally once daily', 0, 'Contraindicated as first-line monotherapy. Beta-blockers are no longer recommended as routine initial monotherapy under NICE NG136 unless there is a compelling cardiac co-indication.', 2, 1789655696);
