INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('39ce7a20-a93c-49e4-a6ae-5c022ec7a13a', '21e254ec-eec6-46ab-8ba1-de4560358d37', 'E', 'Amlodipine 10 mg with no repeat blood pressure monitoring for 12 months', 0, 'Inappropriate dosing and monitoring. Starting at the maximum 10 mg increases ankle oedema risk, and NICE mandates review within 4 to 8 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('4a1bc95b-b8d6-4182-965d-c25e2fcabb91', '21e254ec-eec6-46ab-8ba1-de4560358d37', 'NICE NG136 Step 1: CCB is first-line in patients of Black African origin or patients aged 55+ without diabetes.', 'Blood pressure treatment steps: Step 1 (A/C), Step 2 (A+C or A+D), Step 3 (A+C+D), Step 4 (add low-dose spironolactone if K+ <= 4.5 or alpha/beta-blocker if K+ > 4.5). Reference: NICE NG136: Hypertension in adults (Section 1.4).', 'NICE NG136: Hypertension in adults (Section 1.4)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('ab20ec6f-94b7-4c14-b6d0-541bee5fdba6', '21e254ec-eec6-46ab-8ba1-de4560358d37', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'ACP-Q-0050', 1, 'published', 'p-mpharm', 'sub-acs', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('35bb56ef-6519-4495-9a7b-8d1e9cebf3c4', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'A 40-year-old male patient with newly diagnosed HFrEF (ejection fraction 32%) is currently symptomatically stable on Ramipril 10 mg and Bisoprolol 5 mg. Current eGFR is 54 mL/min and serum potassium is 4.4 mmol/L. (Case Ref: CARDIOVASCULAR-0050). Relevant physiological and medication history have been reviewed.', 'Which addition to the current regimen is recommended by UK guidance to reduce mortality and hospitalisation?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f8ca08b1-621b-4b19-a66c-d03c246022fb', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'A', 'Initiate Dapagliflozin 10 mg once daily and Spironolactone 25 mg once daily', 1, 'Correct. Modern guideline-directed medical therapy (GDMT) mandates foundation quad-therapy: ACEi/ARNI, beta-blocker, MRA (spironolactone), and SGLT2 inhibitor (dapagliflozin/empagliflozin).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('accc9d29-2820-4059-8d9b-dbe08f9410af', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'B', 'Increase Bisoprolol to 10 mg and withhold additional medication classes', 0, 'Sub-optimal. While beta-blocker uptitration is beneficial, rapid multi-class quad-therapy initiation confers greater early mortality reduction.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4d360c5a-d166-4705-8666-7f2d96b0494a', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'C', 'Add Verapamil 120 mg modified-release daily for blood pressure control', 0, 'Strictly contraindicated. Non-dihydropyridine CCBs (verapamil, diltiazem) have negative inotropic effects and worsen outcomes in HFrEF.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c6e49de6-0c6e-4339-905f-7d86c9d5aad8', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'D', 'Add Digoxin 125 mcg daily as initial second-line therapy', 0, 'Deprecated historical usage. Digoxin does not reduce mortality in HFrEF; it is reserved for symptom control in refractory patients or AF rate control.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('87c2c40f-8a84-49e7-ba63-2e1e7d25f520', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('5d9e891f-0857-4a18-9981-6a70a3b982c6', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 'HFrEF foundation quad-therapy includes ACEi/ARNI, Beta-blocker, MRA, and SGLT2 inhibitor.', 'Check renal function and electrolytes before and 1-2 weeks after initiating or increasing MRAs. Reference: NICE NG106 & ESC Heart Failure Guidelines.', 'NICE NG106 & ESC Heart Failure Guidelines', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('ceb60bb0-4e46-49fb-a139-ae6777a3c304', 'bcf98d1e-7633-4ad3-aa8d-2ab6775f5fb1', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'ACP-Q-0051', 1, 'published', 'p-mpharm', 'sub-htn', 'medium', 'sba', 'hospital', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('7a2f695c-998e-496e-8044-2b2056805a23', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'A 47-year-old female patient with non-valvular atrial fibrillation has a CHA2DS2-VASc score of 4 and an ORBIT score of 3. Renal function reveals a CrCl of 42 mL/min. (Case Ref: CARDIOVASCULAR-0051). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate anticoagulation strategy according to NICE NG196?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0ce99a25-fc14-4108-b464-be821ce66526', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'A', 'Apixaban 5 mg twice daily (or standard DOAC dose adjusted for renal function)', 1, 'Correct. A Direct-acting Oral Anticoagulant (DOAC) is first-line over warfarin for non-valvular AF. For apixaban, dose reduction to 2.5 mg bd is only triggered if 2 of 3 criteria apply: age >= 80, weight <= 60kg, serum creatinine >= 133 mcmol/L.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('aa9d8edb-e144-467a-84c2-9ef42b455a65', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'B', 'Warfarin with target INR 2.0 to 3.0', 0, 'Sub-optimal. DOACs demonstrate superior or non-inferior safety and efficacy with lower intracranial haemorrhage rates compared to warfarin.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d4fb613e-1d28-4385-970f-9006b151b4e7', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'C', 'Aspirin 75 mg daily monotherapy', 0, 'Contraindicated. Aspirin monotherapy is explicitly contraindicated for stroke prevention in AF because it provides negligible stroke reduction while increasing major bleeding.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1e4ac0f3-8f70-4bdd-903b-4dc8863ccd68', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ede4128c-d9d4-441b-8be7-691e8aa2a425', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('2037555d-2fee-474e-b595-a2315a1bb2a4', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('fe469845-ae0c-4134-bf10-e690a6fa3c49', '6ef7ae6c-5aed-4102-9d46-13f1927577f2', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
