INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c3843cdf-91c1-416f-bd75-3fefa824450d', '434651d8-08cc-407d-8179-18071c14cc41', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
