INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('652c824f-462a-42f9-bd39-eccbdba1b917', '22857c59-b9f5-478d-9ab8-87e9ac357250', 'C', 'Add Verapamil 120 mg modified-release daily for blood pressure control', 0, 'Strictly contraindicated. Non-dihydropyridine CCBs (verapamil, diltiazem) have negative inotropic effects and worsen outcomes in HFrEF.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2a4c00f0-af14-409a-80c7-142f5b655135', '22857c59-b9f5-478d-9ab8-87e9ac357250', 'D', 'Add Digoxin 125 mcg daily as initial second-line therapy', 0, 'Deprecated historical usage. Digoxin does not reduce mortality in HFrEF; it is reserved for symptom control in refractory patients or AF rate control.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d92eb3d0-351f-4148-bafc-f111398156e8', '22857c59-b9f5-478d-9ab8-87e9ac357250', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('9d51fe61-43bf-4109-8c70-49db15eab3ed', '22857c59-b9f5-478d-9ab8-87e9ac357250', 'HFrEF foundation quad-therapy includes ACEi/ARNI, Beta-blocker, MRA, and SGLT2 inhibitor.', 'Check renal function and electrolytes before and 1-2 weeks after initiating or increasing MRAs. Reference: NICE NG106 & ESC Heart Failure Guidelines.', 'NICE NG106 & ESC Heart Failure Guidelines', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('c4075429-4bd7-4db4-9d85-401cadaec47b', '22857c59-b9f5-478d-9ab8-87e9ac357250', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'ACP-Q-0093', 1, 'published', 'p-mpharm', 'sub-af', 'medium', 'sba', 'hospital', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('19765bdd-c1a3-49db-802a-1da3b840316b', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'A 81-year-old female patient with non-valvular atrial fibrillation has a CHA2DS2-VASc score of 4 and an ORBIT score of 3. Renal function reveals a CrCl of 42 mL/min. (Case Ref: CARDIOVASCULAR-0093). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate anticoagulation strategy according to NICE NG196?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6f3a51b9-8582-41b1-8fc5-a0a8c7e64c27', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'A', 'Apixaban 5 mg twice daily (or standard DOAC dose adjusted for renal function)', 1, 'Correct. A Direct-acting Oral Anticoagulant (DOAC) is first-line over warfarin for non-valvular AF. For apixaban, dose reduction to 2.5 mg bd is only triggered if 2 of 3 criteria apply: age >= 80, weight <= 60kg, serum creatinine >= 133 mcmol/L.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ca377412-a10c-40eb-8a82-39a69d1d1d90', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'B', 'Warfarin with target INR 2.0 to 3.0', 0, 'Sub-optimal. DOACs demonstrate superior or non-inferior safety and efficacy with lower intracranial haemorrhage rates compared to warfarin.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9e400749-4314-4d81-b95b-4d994aab6fba', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'C', 'Aspirin 75 mg daily monotherapy', 0, 'Contraindicated. Aspirin monotherapy is explicitly contraindicated for stroke prevention in AF because it provides negligible stroke reduction while increasing major bleeding.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('97f6f857-1232-407c-bc28-40dcb9bfe97b', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9fed870d-5836-4079-9304-4951a5ec4469', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('fd021549-4c01-4102-96e7-8cd2bfe6e9ec', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('09e47255-89e7-4714-91ec-23a6da415ebd', '2f9a0a9f-e2ae-47e9-8b04-b3038e96c8f3', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('44bb9558-f563-4e12-902f-601a559a3ba9', 'ACP-Q-0094', 1, 'published', 'p-mpharm', 'sub-lipid', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('e5fea412-ce4a-464b-b888-07c792c95c42', '44bb9558-f563-4e12-902f-601a559a3ba9', 'A 23-year-old male patient presents for a medication review following clinic blood pressure measurements averaging 156/96 mmHg (Stage 2 hypertension) confirmed by ABPM. There is no past history of diabetes or proteinuric kidney disease. (Case Ref: CARDIOVASCULAR-0094). Relevant physiological and medication history have been reviewed.', 'In accordance with NICE NG136 guidance, which of the following is the most appropriate initial antihypertensive therapy?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1687739b-7813-4c0e-acc8-5c1ce471577d', '44bb9558-f563-4e12-902f-601a559a3ba9', 'A', 'Amlodipine 5 mg orally once daily', 1, 'Correct. For patients of Black African or African-Caribbean family origin (any age) or adults aged 50 and over without diabetes, Step 1 treatment is a Calcium Channel Blocker (CCB).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bac6c064-985f-4af9-98dc-d14cd3f5ac38', '44bb9558-f563-4e12-902f-601a559a3ba9', 'B', 'Ramipril 2.5 mg orally once daily', 0, 'Sub-optimal. ACE inhibitors or ARBs are first-line for non-Black patients under 55 or adults with type 2 diabetes of any age, but less effective as monotherapy in Black African ancestry.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dc7b31c5-989b-4ce3-adbb-74adfadd4ae3', '44bb9558-f563-4e12-902f-601a559a3ba9', 'C', 'Bisoprolol 5 mg orally once daily', 0, 'Contraindicated as first-line monotherapy. Beta-blockers are no longer recommended as routine initial monotherapy under NICE NG136 unless there is a compelling cardiac co-indication.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1eb9b358-8b02-426a-8195-a1ac354a0695', '44bb9558-f563-4e12-902f-601a559a3ba9', 'D', 'Atenolol 50 mg orally once daily', 0, 'Deprecated historical practice. Atenolol has shown inferior stroke reduction in trials compared to modern CCB/ACEi regimens.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a911249e-5161-49ba-8d71-d371093e41d7', '44bb9558-f563-4e12-902f-601a559a3ba9', 'E', 'Amlodipine 10 mg with no repeat blood pressure monitoring for 12 months', 0, 'Inappropriate dosing and monitoring. Starting at the maximum 10 mg increases ankle oedema risk, and NICE mandates review within 4 to 8 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('2aa58011-75fc-4168-af52-1e891697b0a7', '44bb9558-f563-4e12-902f-601a559a3ba9', 'NICE NG136 Step 1: CCB is first-line in patients of Black African origin or patients aged 55+ without diabetes.', 'Blood pressure treatment steps: Step 1 (A/C), Step 2 (A+C or A+D), Step 3 (A+C+D), Step 4 (add low-dose spironolactone if K+ <= 4.5 or alpha/beta-blocker if K+ > 4.5). Reference: NICE NG136: Hypertension in adults (Section 1.4).', 'NICE NG136: Hypertension in adults (Section 1.4)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('6819c5ee-05b7-4d1e-ab77-808558248628', '44bb9558-f563-4e12-902f-601a559a3ba9', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
