INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('04f2b7a4-c712-4276-9af2-b0d484c4286d', '80ab3411-b85a-4d4e-8004-0294b1cb5fd1', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789655696);
