INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('969fe6e7-753e-40e4-8463-9790eade67c7', '98151226-0164-4969-9015-6be7e8328b09', 'A 33-year-old male patient with non-valvular atrial fibrillation has a CHA2DS2-VASc score of 4 and an ORBIT score of 3. Renal function reveals a CrCl of 42 mL/min. (Case Ref: CARDIOVASCULAR-0114). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate anticoagulation strategy according to NICE NG196?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bd66ee4d-06e4-427e-9668-ed165783b288', '98151226-0164-4969-9015-6be7e8328b09', 'A', 'Apixaban 5 mg twice daily (or standard DOAC dose adjusted for renal function)', 1, 'Correct. A Direct-acting Oral Anticoagulant (DOAC) is first-line over warfarin for non-valvular AF. For apixaban, dose reduction to 2.5 mg bd is only triggered if 2 of 3 criteria apply: age >= 80, weight <= 60kg, serum creatinine >= 133 mcmol/L.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3ddcd0e3-4c45-4d6e-a7de-27ea073f80d1', '98151226-0164-4969-9015-6be7e8328b09', 'B', 'Warfarin with target INR 2.0 to 3.0', 0, 'Sub-optimal. DOACs demonstrate superior or non-inferior safety and efficacy with lower intracranial haemorrhage rates compared to warfarin.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('341d3240-a072-4283-84f8-fbda1d3cf2b8', '98151226-0164-4969-9015-6be7e8328b09', 'C', 'Aspirin 75 mg daily monotherapy', 0, 'Contraindicated. Aspirin monotherapy is explicitly contraindicated for stroke prevention in AF because it provides negligible stroke reduction while increasing major bleeding.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('db3f4b0e-bf97-4419-97e6-9dea36619890', '98151226-0164-4969-9015-6be7e8328b09', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a5b15963-021c-44ae-b65e-bd53b754a372', '98151226-0164-4969-9015-6be7e8328b09', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('b2419d3c-969d-4c62-9a3d-474b3f5ba774', '98151226-0164-4969-9015-6be7e8328b09', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('8e8d6bd7-4ff1-496a-bf13-fde2e2190797', '98151226-0164-4969-9015-6be7e8328b09', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('1c773273-75f2-4aff-b132-bf0950c9ef6a', 'ACP-Q-0115', 1, 'published', 'p-mpharm', 'sub-acs', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('23574e6a-553b-43a6-b269-4a66d1e6d933', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'A 40-year-old female patient presents for a medication review following clinic blood pressure measurements averaging 156/96 mmHg (Stage 2 hypertension) confirmed by ABPM. There is no past history of diabetes or proteinuric kidney disease. (Case Ref: CARDIOVASCULAR-0115). Relevant physiological and medication history have been reviewed.', 'In accordance with NICE NG136 guidance, which of the following is the most appropriate initial antihypertensive therapy?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1e3cad94-f483-47f0-90ab-c0c018fd239f', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'A', 'Amlodipine 5 mg orally once daily', 1, 'Correct. For patients of Black African or African-Caribbean family origin (any age) or adults aged 50 and over without diabetes, Step 1 treatment is a Calcium Channel Blocker (CCB).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0fee037d-bcff-40ea-9a8d-60f2ff822496', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'B', 'Ramipril 2.5 mg orally once daily', 0, 'Sub-optimal. ACE inhibitors or ARBs are first-line for non-Black patients under 55 or adults with type 2 diabetes of any age, but less effective as monotherapy in Black African ancestry.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ce771f6d-e5b6-49b6-9b07-5dd44bcbe389', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'C', 'Bisoprolol 5 mg orally once daily', 0, 'Contraindicated as first-line monotherapy. Beta-blockers are no longer recommended as routine initial monotherapy under NICE NG136 unless there is a compelling cardiac co-indication.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('56e63908-1bc3-47b2-88ce-8d4e7a5c35bc', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'D', 'Atenolol 50 mg orally once daily', 0, 'Deprecated historical practice. Atenolol has shown inferior stroke reduction in trials compared to modern CCB/ACEi regimens.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bd5a0b71-4e57-48f9-aae4-5e569a51d278', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'E', 'Amlodipine 10 mg with no repeat blood pressure monitoring for 12 months', 0, 'Inappropriate dosing and monitoring. Starting at the maximum 10 mg increases ankle oedema risk, and NICE mandates review within 4 to 8 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('6e959115-c29f-4ec0-86b1-f6102b677e9b', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 'NICE NG136 Step 1: CCB is first-line in patients of Black African origin or patients aged 55+ without diabetes.', 'Blood pressure treatment steps: Step 1 (A/C), Step 2 (A+C or A+D), Step 3 (A+C+D), Step 4 (add low-dose spironolactone if K+ <= 4.5 or alpha/beta-blocker if K+ > 4.5). Reference: NICE NG136: Hypertension in adults (Section 1.4).', 'NICE NG136: Hypertension in adults (Section 1.4)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('50218ba8-9dc0-4ac8-aad2-3b09d1714a60', '1c773273-75f2-4aff-b132-bf0950c9ef6a', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'ACP-Q-0116', 1, 'published', 'p-mpharm', 'sub-htn', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('03240eea-4981-4c73-8532-f2ddb3bc55e3', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'A 47-year-old male patient with newly diagnosed HFrEF (ejection fraction 32%) is currently symptomatically stable on Ramipril 10 mg and Bisoprolol 5 mg. Current eGFR is 54 mL/min and serum potassium is 4.4 mmol/L. (Case Ref: CARDIOVASCULAR-0116). Relevant physiological and medication history have been reviewed.', 'Which addition to the current regimen is recommended by UK guidance to reduce mortality and hospitalisation?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('62fcfe77-3654-4ba1-8777-51e1fbf845c0', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'A', 'Initiate Dapagliflozin 10 mg once daily and Spironolactone 25 mg once daily', 1, 'Correct. Modern guideline-directed medical therapy (GDMT) mandates foundation quad-therapy: ACEi/ARNI, beta-blocker, MRA (spironolactone), and SGLT2 inhibitor (dapagliflozin/empagliflozin).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('43ab98ff-ae0a-4e2e-8449-874b2dd467b4', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'B', 'Increase Bisoprolol to 10 mg and withhold additional medication classes', 0, 'Sub-optimal. While beta-blocker uptitration is beneficial, rapid multi-class quad-therapy initiation confers greater early mortality reduction.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b509b48d-d8ec-4d11-a9f8-cf92969317f1', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'C', 'Add Verapamil 120 mg modified-release daily for blood pressure control', 0, 'Strictly contraindicated. Non-dihydropyridine CCBs (verapamil, diltiazem) have negative inotropic effects and worsen outcomes in HFrEF.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dcb93a04-abde-4cef-ba4f-67846aed7468', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'D', 'Add Digoxin 125 mcg daily as initial second-line therapy', 0, 'Deprecated historical usage. Digoxin does not reduce mortality in HFrEF; it is reserved for symptom control in refractory patients or AF rate control.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f6798d5d-580e-4375-83ce-3caa586a5041', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('c2cede0e-b378-42b2-8ed4-7c784ebc7c53', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 'HFrEF foundation quad-therapy includes ACEi/ARNI, Beta-blocker, MRA, and SGLT2 inhibitor.', 'Check renal function and electrolytes before and 1-2 weeks after initiating or increasing MRAs. Reference: NICE NG106 & ESC Heart Failure Guidelines.', 'NICE NG106 & ESC Heart Failure Guidelines', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('32b7403a-f7d2-43b4-b043-76356131eb1f', '5bf1c12a-d80a-4af9-be07-89c60a9599f8', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
