INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('b74613f5-76e8-4686-a24b-db77e4f1923a', 'ACP-Q-0146', 1, 'published', 'p-mpharm', 'sub-htn', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('d7f9c48d-b340-471e-8cee-8f5a7d60bdb2', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'A 62-year-old male patient with newly diagnosed HFrEF (ejection fraction 32%) is currently symptomatically stable on Ramipril 10 mg and Bisoprolol 5 mg. Current eGFR is 54 mL/min and serum potassium is 4.4 mmol/L. (Case Ref: CARDIOVASCULAR-0146). Relevant physiological and medication history have been reviewed.', 'Which addition to the current regimen is recommended by UK guidance to reduce mortality and hospitalisation?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7a5fb54e-6718-48ee-b0c5-06f46358306e', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'A', 'Initiate Dapagliflozin 10 mg once daily and Spironolactone 25 mg once daily', 1, 'Correct. Modern guideline-directed medical therapy (GDMT) mandates foundation quad-therapy: ACEi/ARNI, beta-blocker, MRA (spironolactone), and SGLT2 inhibitor (dapagliflozin/empagliflozin).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5ce6e93e-5b28-400a-98ef-6440f4279e6c', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'B', 'Increase Bisoprolol to 10 mg and withhold additional medication classes', 0, 'Sub-optimal. While beta-blocker uptitration is beneficial, rapid multi-class quad-therapy initiation confers greater early mortality reduction.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d6a47397-24b8-47ba-b8f0-9e79701557b3', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'C', 'Add Verapamil 120 mg modified-release daily for blood pressure control', 0, 'Strictly contraindicated. Non-dihydropyridine CCBs (verapamil, diltiazem) have negative inotropic effects and worsen outcomes in HFrEF.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('385b1d19-4d30-4a44-bb9e-5a5ee599f72e', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'D', 'Add Digoxin 125 mcg daily as initial second-line therapy', 0, 'Deprecated historical usage. Digoxin does not reduce mortality in HFrEF; it is reserved for symptom control in refractory patients or AF rate control.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3c9a8bf2-d1f0-463a-b8db-09283ab780de', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('8074d0c9-d0b8-4fda-a72c-5d3c3bae9995', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 'HFrEF foundation quad-therapy includes ACEi/ARNI, Beta-blocker, MRA, and SGLT2 inhibitor.', 'Check renal function and electrolytes before and 1-2 weeks after initiating or increasing MRAs. Reference: NICE NG106 & ESC Heart Failure Guidelines.', 'NICE NG106 & ESC Heart Failure Guidelines', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('ee66822a-85f3-44ca-b95c-291d0998f899', 'b74613f5-76e8-4686-a24b-db77e4f1923a', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'ACP-Q-0147', 1, 'published', 'p-mpharm', 'sub-hf', 'medium', 'sba', 'hospital', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('02b2c570-3249-4813-81e6-b1c7494b72fb', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'A 69-year-old female patient with non-valvular atrial fibrillation has a CHA2DS2-VASc score of 4 and an ORBIT score of 3. Renal function reveals a CrCl of 42 mL/min. (Case Ref: CARDIOVASCULAR-0147). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate anticoagulation strategy according to NICE NG196?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('13cbc8d5-398d-4e1a-a962-561b0ef907a2', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'A', 'Apixaban 5 mg twice daily (or standard DOAC dose adjusted for renal function)', 1, 'Correct. A Direct-acting Oral Anticoagulant (DOAC) is first-line over warfarin for non-valvular AF. For apixaban, dose reduction to 2.5 mg bd is only triggered if 2 of 3 criteria apply: age >= 80, weight <= 60kg, serum creatinine >= 133 mcmol/L.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6514bb57-9af4-49ec-a595-8ca7246886ef', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'B', 'Warfarin with target INR 2.0 to 3.0', 0, 'Sub-optimal. DOACs demonstrate superior or non-inferior safety and efficacy with lower intracranial haemorrhage rates compared to warfarin.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('45f3c6b2-5ecb-4c0a-9f0c-beeb77161e54', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'C', 'Aspirin 75 mg daily monotherapy', 0, 'Contraindicated. Aspirin monotherapy is explicitly contraindicated for stroke prevention in AF because it provides negligible stroke reduction while increasing major bleeding.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c6cfab49-0d93-4154-ba6f-393f0939848b', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e9e2e7a6-7d5a-4ab4-9e5c-8e689e354f7d', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('79696417-752c-47ee-b2aa-1f393ca284de', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('c761fd95-497c-4cd6-b7bc-0a07fd79367c', '9192fbef-4370-4e8b-a7f7-4bb4aa159266', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('f24c2762-b144-4394-819a-8a26b9920d04', 'ACP-Q-0148', 1, 'published', 'p-mpharm', 'sub-af', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('a34bd7be-7bb2-4a6b-ae0f-1ab8d5e3220d', 'f24c2762-b144-4394-819a-8a26b9920d04', 'A 76-year-old male patient presents for a medication review following clinic blood pressure measurements averaging 156/96 mmHg (Stage 2 hypertension) confirmed by ABPM. There is no past history of diabetes or proteinuric kidney disease. (Case Ref: CARDIOVASCULAR-0148). Relevant physiological and medication history have been reviewed.', 'In accordance with NICE NG136 guidance, which of the following is the most appropriate initial antihypertensive therapy?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0f276a5c-b6e9-4be2-ab58-1b29be77feb7', 'f24c2762-b144-4394-819a-8a26b9920d04', 'A', 'Amlodipine 5 mg orally once daily', 1, 'Correct. For patients of Black African or African-Caribbean family origin (any age) or adults aged 50 and over without diabetes, Step 1 treatment is a Calcium Channel Blocker (CCB).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('397ede28-e599-41da-955e-6e1c6c3a4b19', 'f24c2762-b144-4394-819a-8a26b9920d04', 'B', 'Ramipril 2.5 mg orally once daily', 0, 'Sub-optimal. ACE inhibitors or ARBs are first-line for non-Black patients under 55 or adults with type 2 diabetes of any age, but less effective as monotherapy in Black African ancestry.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('653bba49-7778-4f9c-b1af-3399e9b4491d', 'f24c2762-b144-4394-819a-8a26b9920d04', 'C', 'Bisoprolol 5 mg orally once daily', 0, 'Contraindicated as first-line monotherapy. Beta-blockers are no longer recommended as routine initial monotherapy under NICE NG136 unless there is a compelling cardiac co-indication.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9884df26-9791-4089-b25a-8b16019d6dbb', 'f24c2762-b144-4394-819a-8a26b9920d04', 'D', 'Atenolol 50 mg orally once daily', 0, 'Deprecated historical practice. Atenolol has shown inferior stroke reduction in trials compared to modern CCB/ACEi regimens.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('37cc1406-f4f1-4aac-97a9-c0a81173c104', 'f24c2762-b144-4394-819a-8a26b9920d04', 'E', 'Amlodipine 10 mg with no repeat blood pressure monitoring for 12 months', 0, 'Inappropriate dosing and monitoring. Starting at the maximum 10 mg increases ankle oedema risk, and NICE mandates review within 4 to 8 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('fbda6ce6-51d7-48c3-967e-1698445d9020', 'f24c2762-b144-4394-819a-8a26b9920d04', 'NICE NG136 Step 1: CCB is first-line in patients of Black African origin or patients aged 55+ without diabetes.', 'Blood pressure treatment steps: Step 1 (A/C), Step 2 (A+C or A+D), Step 3 (A+C+D), Step 4 (add low-dose spironolactone if K+ <= 4.5 or alpha/beta-blocker if K+ > 4.5). Reference: NICE NG136: Hypertension in adults (Section 1.4).', 'NICE NG136: Hypertension in adults (Section 1.4)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('124c33c5-39ce-4005-9ee4-eb504186e5c6', 'f24c2762-b144-4394-819a-8a26b9920d04', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
