INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5e685950-bccc-4def-89b8-fd789dcd8bc1', '657d7376-4496-45c9-907c-6373ecb094f7', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d1a1ddb0-2259-4354-869f-620984194424', '657d7376-4496-45c9-907c-6373ecb094f7', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ec6be40d-9e30-4a97-9c88-f8fe30104947', '657d7376-4496-45c9-907c-6373ecb094f7', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('90f6c240-e027-4eea-ab08-1bf185bb654b', '657d7376-4496-45c9-907c-6373ecb094f7', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'ACP-Q-0157', 1, 'published', 'p-mpharm', 'sub-hf', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('bc0258a5-4456-4eb8-8d4f-cdcd6f9fee7d', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'A 74-year-old female patient presents for a medication review following clinic blood pressure measurements averaging 156/96 mmHg (Stage 2 hypertension) confirmed by ABPM. There is no past history of diabetes or proteinuric kidney disease. (Case Ref: CARDIOVASCULAR-0157). Relevant physiological and medication history have been reviewed.', 'In accordance with NICE NG136 guidance, which of the following is the most appropriate initial antihypertensive therapy?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4d89c19b-5db7-452d-a269-572365acde9d', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'A', 'Amlodipine 5 mg orally once daily', 1, 'Correct. For patients of Black African or African-Caribbean family origin (any age) or adults aged 50 and over without diabetes, Step 1 treatment is a Calcium Channel Blocker (CCB).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d77a57ef-7459-40c3-a03f-70e4edffec1b', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'B', 'Ramipril 2.5 mg orally once daily', 0, 'Sub-optimal. ACE inhibitors or ARBs are first-line for non-Black patients under 55 or adults with type 2 diabetes of any age, but less effective as monotherapy in Black African ancestry.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('49974ee6-bd44-4a06-a28d-6cb117302148', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'C', 'Bisoprolol 5 mg orally once daily', 0, 'Contraindicated as first-line monotherapy. Beta-blockers are no longer recommended as routine initial monotherapy under NICE NG136 unless there is a compelling cardiac co-indication.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('803ea4ba-51f0-4f3f-a201-d28bdfdf4589', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'D', 'Atenolol 50 mg orally once daily', 0, 'Deprecated historical practice. Atenolol has shown inferior stroke reduction in trials compared to modern CCB/ACEi regimens.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('aafe3657-a058-4c21-a8e3-173af40bf6a1', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'E', 'Amlodipine 10 mg with no repeat blood pressure monitoring for 12 months', 0, 'Inappropriate dosing and monitoring. Starting at the maximum 10 mg increases ankle oedema risk, and NICE mandates review within 4 to 8 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('2097ba0d-987e-4cea-8798-b5f61bcb29eb', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 'NICE NG136 Step 1: CCB is first-line in patients of Black African origin or patients aged 55+ without diabetes.', 'Blood pressure treatment steps: Step 1 (A/C), Step 2 (A+C or A+D), Step 3 (A+C+D), Step 4 (add low-dose spironolactone if K+ <= 4.5 or alpha/beta-blocker if K+ > 4.5). Reference: NICE NG136: Hypertension in adults (Section 1.4).', 'NICE NG136: Hypertension in adults (Section 1.4)', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('22a67aa1-b401-441a-a93f-4ee5bd3f13fe', '7c6cd950-1285-4f19-a0ad-fda7f44c92e1', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('d9d79167-9cc8-455d-a573-2cfeead09871', 'ACP-Q-0158', 1, 'published', 'p-mpharm', 'sub-af', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ff2d83c1-5635-4ae6-be9d-2794fbebf245', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'A 81-year-old male patient with newly diagnosed HFrEF (ejection fraction 32%) is currently symptomatically stable on Ramipril 10 mg and Bisoprolol 5 mg. Current eGFR is 54 mL/min and serum potassium is 4.4 mmol/L. (Case Ref: CARDIOVASCULAR-0158). Relevant physiological and medication history have been reviewed.', 'Which addition to the current regimen is recommended by UK guidance to reduce mortality and hospitalisation?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b121207c-6095-4eff-82a6-ff27b6672ccc', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'A', 'Initiate Dapagliflozin 10 mg once daily and Spironolactone 25 mg once daily', 1, 'Correct. Modern guideline-directed medical therapy (GDMT) mandates foundation quad-therapy: ACEi/ARNI, beta-blocker, MRA (spironolactone), and SGLT2 inhibitor (dapagliflozin/empagliflozin).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ada77fc2-f200-42ec-bafc-fe27b8546d5a', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'B', 'Increase Bisoprolol to 10 mg and withhold additional medication classes', 0, 'Sub-optimal. While beta-blocker uptitration is beneficial, rapid multi-class quad-therapy initiation confers greater early mortality reduction.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dc4d98bb-09b6-4cf1-8b2b-d426c12ffe79', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'C', 'Add Verapamil 120 mg modified-release daily for blood pressure control', 0, 'Strictly contraindicated. Non-dihydropyridine CCBs (verapamil, diltiazem) have negative inotropic effects and worsen outcomes in HFrEF.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e593f709-d028-4985-975f-245b3829dc30', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'D', 'Add Digoxin 125 mcg daily as initial second-line therapy', 0, 'Deprecated historical usage. Digoxin does not reduce mortality in HFrEF; it is reserved for symptom control in refractory patients or AF rate control.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ad166ab5-a8fa-4260-b8cd-f7b734b0f752', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e9432394-6347-43a9-985f-4a0b4c326ef0', 'd9d79167-9cc8-455d-a573-2cfeead09871', 'HFrEF foundation quad-therapy includes ACEi/ARNI, Beta-blocker, MRA, and SGLT2 inhibitor.', 'Check renal function and electrolytes before and 1-2 weeks after initiating or increasing MRAs. Reference: NICE NG106 & ESC Heart Failure Guidelines.', 'NICE NG106 & ESC Heart Failure Guidelines', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('bd281dbe-d62b-4b28-a96e-102794ff6108', 'd9d79167-9cc8-455d-a573-2cfeead09871', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
