INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2b7310ea-06e8-4151-a0da-40f18f4f8155', '04a95a39-5625-4054-931d-171bf7868b79', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ba2b767a-6e9e-41b1-804c-ec8360fecfe5', '04a95a39-5625-4054-931d-171bf7868b79', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789655696);
