INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('83105fd2-395f-4ef6-a589-efd24ae79ff2', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'A 77-year-old male patient A hospital patient is prescribed 1 litre of sodium chloride 0.9% containing 40 mmol potassium chloride to be infused over 8 hours. The giving set delivers 20 drops per mL. (Case Ref: CALCULATIONS-0206). Relevant physiological and medication history have been reviewed.', 'What is the required infusion rate in drops per minute (drops/min)? Round to the nearest whole drop.', '42', '1', 'drops/min', NULL, 1, '(1000 * 20) / (8 * 60) = 20000 / 480 = 41.67 drops/min = 42 drops/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('82e1c183-9abe-4b65-8ffd-68874064fb21', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'A', '42 drops/min', 1, 'Correct. Total volume = 1,000 mL. Total time = 8 hours * 60 minutes = 480 minutes. Total drops = 1,000 mL * 20 drops/mL = 20,000 drops. 20,000 / 480 = 41.67 drops/min = 42 drops/min.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6ad74556-2f61-4deb-a3e6-6904ed35a81e', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'B', '21 drops/min (calculated based on 10 drops/mL giving set)', 0, 'Incorrect giving set factor used.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('74ebce75-a832-43c3-b8db-02725b4aa6d1', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'C', '83 drops/min (exceeds safe maximum IV potassium infusion rate of 20 mmol/hr)', 0, 'Unsafe infusion rate causing cardiac arrest risk from rapid potassium administration.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b355f147-44e7-4763-a427-7e1f86c72791', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2015904c-d09d-4cee-ae41-d078f87186ad', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('99538180-5d75-4c93-ad86-b113fc4efe3d', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('61f69862-516a-4208-ab6d-1496f85131c8', '90abc4dc-0cae-46e3-9f2d-247bb3052550', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('9c3a2f93-51e1-4e1e-b545-71596710d381', 'ACP-Q-0207', 1, 'published', 'p-mpharm', 'sub-infusions', 'medium', 'calculation', 'hospital', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('34a587b4-d329-4907-bd35-4dafaf37e82f', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'A 84-year-old female patient A 74-year-old female patient weighing 58 kg presents with serum creatinine of 115 micromol/L. She is being assessed for apixaban stroke prevention in non-valvular atrial fibrillation. (Case Ref: CALCULATIONS-0207). Relevant physiological and medication history have been reviewed.', 'Calculate the patient’s estimated creatinine clearance (CrCl) in mL/min using the Cockcroft-Gault formula. Give your answer to the nearest whole number.', '37', '1', 'mL/min', NULL, 1, '((140 - 74) * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 mL/min. With 1.04 constant = 37.3 mL/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d727cffd-d130-4744-b188-832e43319a68', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'A', '37 mL/min', 1, 'Correct. Cockcroft-Gault formula: ((140 - Age) * Weight in kg * 1.04) / Serum Creatinine in micromol/L. ((140 - 74) * 58 * 1.04) / 115 = (66 * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 -> adjusted for female factor = 37.8 mL/min (approx 35-37 mL/min depending on constant 1.04 vs 0.85).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('47378a14-7d5b-4a47-a1bc-1dda8a1fb265', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'B', '44 mL/min (omitted female correction factor of 1.04 vs 1.23 for males)', 0, 'Incorrect. Forgets female adjustment factor (1.04).', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6f633cec-aed1-4adb-8dcb-8ea5e915a26c', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'C', '52 mL/min (used MDRD eGFR instead of Cockcroft-Gault CrCl)', 0, 'Clinically unsafe. MHRA specifically warns against using eGFR for drug dosing in older adults or extreme weights.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b89abecc-f522-455a-8ec6-3e03c55a9542', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'D', '25 mL/min (severe underestimation)', 0, 'Calculation error leading to inappropriate drug discontinuation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bce73e43-b270-4b6e-9035-d1b73a7cc36b', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'E', '60 mL/min (assumed normal without calculation)', 0, 'Presuming renal clearance based purely on age without calculation is clinically dangerous.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('0f1f7558-a729-4858-9a63-616734330803', '9c3a2f93-51e1-4e1e-b545-71596710d381', 'Always use the Cockcroft-Gault formula for renal dose adjustments: Male: ((140-age)*wt*1.23)/Cr; Female: ((140-age)*wt*1.04)/Cr.', 'Units: Age (years), Weight (kg), Serum Creatinine (micromol/L). Reference: GPhC Calculations Guidance & BNF Dosing Framework.', 'GPhC Calculations Guidance & BNF Dosing Framework', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('32f1ad40-4416-45c1-b972-7235fd7e647a', '9c3a2f93-51e1-4e1e-b545-71596710d381', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
