INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('925889d4-77d5-4a3f-85e2-86ddc18fe774', 'df0ec94e-209e-4c6e-9893-e582e9b55c19', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('9ad7fb91-941a-4d4f-b340-d59854e4e8cc', 'df0ec94e-209e-4c6e-9893-e582e9b55c19', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('b37c6ee7-4c0b-4e1e-827a-702db92ee1b4', 'df0ec94e-209e-4c6e-9893-e582e9b55c19', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'ACP-Q-0267', 1, 'published', 'p-mpharm', 'sub-infusions', 'medium', 'calculation', 'hospital', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('6c3bfebc-868a-488d-8629-8941c4a5e1a8', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'A 49-year-old female patient A 74-year-old female patient weighing 58 kg presents with serum creatinine of 115 micromol/L. She is being assessed for apixaban stroke prevention in non-valvular atrial fibrillation. (Case Ref: CALCULATIONS-0267). Relevant physiological and medication history have been reviewed.', 'Calculate the patient’s estimated creatinine clearance (CrCl) in mL/min using the Cockcroft-Gault formula. Give your answer to the nearest whole number.', '37', '1', 'mL/min', NULL, 1, '((140 - 74) * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 mL/min. With 1.04 constant = 37.3 mL/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4396cbe3-f265-4046-bdaa-4e8feaf5d0d0', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'A', '37 mL/min', 1, 'Correct. Cockcroft-Gault formula: ((140 - Age) * Weight in kg * 1.04) / Serum Creatinine in micromol/L. ((140 - 74) * 58 * 1.04) / 115 = (66 * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 -> adjusted for female factor = 37.8 mL/min (approx 35-37 mL/min depending on constant 1.04 vs 0.85).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('694bf4cc-cf23-4709-8da4-39813cf59ed3', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'B', '44 mL/min (omitted female correction factor of 1.04 vs 1.23 for males)', 0, 'Incorrect. Forgets female adjustment factor (1.04).', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('122d5426-0f3f-488d-a4a4-686c5cb88129', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'C', '52 mL/min (used MDRD eGFR instead of Cockcroft-Gault CrCl)', 0, 'Clinically unsafe. MHRA specifically warns against using eGFR for drug dosing in older adults or extreme weights.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('87c9c5ae-e239-434b-881b-61eadbd30a05', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'D', '25 mL/min (severe underestimation)', 0, 'Calculation error leading to inappropriate drug discontinuation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('617f6371-0185-4c0c-8cd3-1f54286e1488', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'E', '60 mL/min (assumed normal without calculation)', 0, 'Presuming renal clearance based purely on age without calculation is clinically dangerous.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ab9035c2-5be2-4990-abe6-55c810c8bcea', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 'Always use the Cockcroft-Gault formula for renal dose adjustments: Male: ((140-age)*wt*1.23)/Cr; Female: ((140-age)*wt*1.04)/Cr.', 'Units: Age (years), Weight (kg), Serum Creatinine (micromol/L). Reference: GPhC Calculations Guidance & BNF Dosing Framework.', 'GPhC Calculations Guidance & BNF Dosing Framework', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('5a815cb8-774f-421c-9db6-87e400df150a', 'c9aa4255-9307-4f6c-85d8-8148dafd7ecd', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('b1161a19-5bec-4806-986a-09ee3204661d', 'ACP-Q-0268', 1, 'published', 'p-mpharm', 'sub-displacements', 'easy', 'calculation', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('46c250ad-eb65-4645-9456-cbc4e3f61616', 'b1161a19-5bec-4806-986a-09ee3204661d', 'A 56-year-old male patient A hospital patient is prescribed 1 litre of sodium chloride 0.9% containing 40 mmol potassium chloride to be infused over 8 hours. The giving set delivers 20 drops per mL. (Case Ref: CALCULATIONS-0268). Relevant physiological and medication history have been reviewed.', 'What is the required infusion rate in drops per minute (drops/min)? Round to the nearest whole drop.', '42', '1', 'drops/min', NULL, 1, '(1000 * 20) / (8 * 60) = 20000 / 480 = 41.67 drops/min = 42 drops/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6c23dfc1-7c32-4714-8f92-d5366a17ff55', 'b1161a19-5bec-4806-986a-09ee3204661d', 'A', '42 drops/min', 1, 'Correct. Total volume = 1,000 mL. Total time = 8 hours * 60 minutes = 480 minutes. Total drops = 1,000 mL * 20 drops/mL = 20,000 drops. 20,000 / 480 = 41.67 drops/min = 42 drops/min.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('98f0d308-ae9e-4a88-a419-51b8cfc76c8b', 'b1161a19-5bec-4806-986a-09ee3204661d', 'B', '21 drops/min (calculated based on 10 drops/mL giving set)', 0, 'Incorrect giving set factor used.', 1, 1789655696);
