INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d3df8b11-d75d-48fb-bc25-218f2d9289ab', 'b1161a19-5bec-4806-986a-09ee3204661d', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('89e251bc-a4f3-4f14-8e6f-6b922642d38f', 'b1161a19-5bec-4806-986a-09ee3204661d', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789655696);
