INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('b9d231db-ea95-4522-90d3-beb8ce58c5bc', '10f6baf4-dc1b-4e05-b44c-4529cb3e8068', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('708c5493-51df-443b-8a36-c19e38a69098', '10f6baf4-dc1b-4e05-b44c-4529cb3e8068', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('03cb2c00-b2f2-45fd-95ba-48a376272890', 'ACP-Q-0311', 1, 'published', 'p-mpharm', 'sub-crcl', 'hard', 'calculation', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('084d98d6-901d-4be7-833f-05552656d512', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'A 32-year-old female patient A 74-year-old female patient weighing 58 kg presents with serum creatinine of 115 micromol/L. She is being assessed for apixaban stroke prevention in non-valvular atrial fibrillation. (Case Ref: CALCULATIONS-0311). Relevant physiological and medication history have been reviewed.', 'Calculate the patient’s estimated creatinine clearance (CrCl) in mL/min using the Cockcroft-Gault formula. Give your answer to the nearest whole number.', '37', '1', 'mL/min', NULL, 1, '((140 - 74) * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 mL/min. With 1.04 constant = 37.3 mL/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0a3fd113-90cb-4832-815b-3979c9790a75', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'A', '37 mL/min', 1, 'Correct. Cockcroft-Gault formula: ((140 - Age) * Weight in kg * 1.04) / Serum Creatinine in micromol/L. ((140 - 74) * 58 * 1.04) / 115 = (66 * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 -> adjusted for female factor = 37.8 mL/min (approx 35-37 mL/min depending on constant 1.04 vs 0.85).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3e15c4cc-012e-4c41-b0c4-dfd546162bf3', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'B', '44 mL/min (omitted female correction factor of 1.04 vs 1.23 for males)', 0, 'Incorrect. Forgets female adjustment factor (1.04).', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ef129673-3a31-42bc-a142-08f01b3b6068', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'C', '52 mL/min (used MDRD eGFR instead of Cockcroft-Gault CrCl)', 0, 'Clinically unsafe. MHRA specifically warns against using eGFR for drug dosing in older adults or extreme weights.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ef4173cf-c981-4462-b735-ee104d8c7999', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'D', '25 mL/min (severe underestimation)', 0, 'Calculation error leading to inappropriate drug discontinuation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1e2aa2bf-baf7-4753-8e5b-30e2220415b9', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'E', '60 mL/min (assumed normal without calculation)', 0, 'Presuming renal clearance based purely on age without calculation is clinically dangerous.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ba6a5f53-6048-463b-a554-62862df51372', '03cb2c00-b2f2-45fd-95ba-48a376272890', 'Always use the Cockcroft-Gault formula for renal dose adjustments: Male: ((140-age)*wt*1.23)/Cr; Female: ((140-age)*wt*1.04)/Cr.', 'Units: Age (years), Weight (kg), Serum Creatinine (micromol/L). Reference: GPhC Calculations Guidance & BNF Dosing Framework.', 'GPhC Calculations Guidance & BNF Dosing Framework', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('b76b03f2-0f73-4b67-be72-c9d35fe0895e', '03cb2c00-b2f2-45fd-95ba-48a376272890', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('6901b01e-3424-4164-bdd5-4a950106c3ff', 'ACP-Q-0312', 1, 'published', 'p-mpharm', 'sub-infusions', 'easy', 'calculation', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('8e8fb63e-548d-463b-bce4-7e0b2f407541', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'A 39-year-old male patient A hospital patient is prescribed 1 litre of sodium chloride 0.9% containing 40 mmol potassium chloride to be infused over 8 hours. The giving set delivers 20 drops per mL. (Case Ref: CALCULATIONS-0312). Relevant physiological and medication history have been reviewed.', 'What is the required infusion rate in drops per minute (drops/min)? Round to the nearest whole drop.', '42', '1', 'drops/min', NULL, 1, '(1000 * 20) / (8 * 60) = 20000 / 480 = 41.67 drops/min = 42 drops/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('847efc5a-f8b5-41f5-97e6-209c6fab3d44', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'A', '42 drops/min', 1, 'Correct. Total volume = 1,000 mL. Total time = 8 hours * 60 minutes = 480 minutes. Total drops = 1,000 mL * 20 drops/mL = 20,000 drops. 20,000 / 480 = 41.67 drops/min = 42 drops/min.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('487bf9a5-d15d-437b-a7ef-373a0c62047c', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'B', '21 drops/min (calculated based on 10 drops/mL giving set)', 0, 'Incorrect giving set factor used.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c2c901ea-cfa4-4779-8a86-25e455482315', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'C', '83 drops/min (exceeds safe maximum IV potassium infusion rate of 20 mmol/hr)', 0, 'Unsafe infusion rate causing cardiac arrest risk from rapid potassium administration.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a872ac64-2771-40c4-8216-b2df833634f2', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d5f98331-930c-4070-9200-9af4b952fb85', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('4aac04fd-2361-4544-901b-bd2d156f1178', '6901b01e-3424-4164-bdd5-4a950106c3ff', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789655696, 1789655696);
