INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('0fcb1e2c-8cda-4b72-8c26-6d63d5aa07ca', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'A 40-year-old male patient A hospital patient is prescribed 1 litre of sodium chloride 0.9% containing 40 mmol potassium chloride to be infused over 8 hours. The giving set delivers 20 drops per mL. (Case Ref: CALCULATIONS-0340). Relevant physiological and medication history have been reviewed.', 'What is the required infusion rate in drops per minute (drops/min)? Round to the nearest whole drop.', '42', '1', 'drops/min', NULL, 1, '(1000 * 20) / (8 * 60) = 20000 / 480 = 41.67 drops/min = 42 drops/min.', 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b853a5c0-6e6e-41c0-9108-a706802c4649', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'A', '42 drops/min', 1, 'Correct. Total volume = 1,000 mL. Total time = 8 hours * 60 minutes = 480 minutes. Total drops = 1,000 mL * 20 drops/mL = 20,000 drops. 20,000 / 480 = 41.67 drops/min = 42 drops/min.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('896b6685-59c0-48eb-9532-9380e3eb0b3c', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'B', '21 drops/min (calculated based on 10 drops/mL giving set)', 0, 'Incorrect giving set factor used.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('facd5b09-51cb-42d0-8fc3-22815f2befe2', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'C', '83 drops/min (exceeds safe maximum IV potassium infusion rate of 20 mmol/hr)', 0, 'Unsafe infusion rate causing cardiac arrest risk from rapid potassium administration.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3aa8fbb1-1a59-4676-9071-d9f1644f7b92', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e86ece86-ac14-48e3-9570-1b5a5a9432b4', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('13b6e578-82c8-4c06-a232-f8066cb49eea', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('b4e766cb-40cf-488f-a34b-657bcfecb0aa', '3549be64-fb58-4767-95ea-bbc86c93f2c7', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('df964263-f2a3-4414-8263-cef0104dc5c4', 'ACP-Q-0341', 1, 'published', 'p-mpharm', 'sub-epilepsy', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('0e93fe2e-30c3-4fdf-92eb-ffd9036005b0', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'A 22-year-old female patient A 26-year-old female with generalised epilepsy attends community pharmacy for a repeat prescription of Sodium Valproate 500 mg tablets. She mentions she stopped using contraception two months ago. (Case Ref: CNS-0341). Relevant physiological and medication history have been reviewed.', 'What is the essential action for the pharmacist to take before dispensing this medication?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fc4af2b0-c6f8-44e7-b436-a2d82c16c65a', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'A', 'Confirm active enrollment in the Valproate Pregnancy Prevention Programme (prevent) with signed Annual Risk Acknowledgement and immediate referral to prescriber', 1, 'Correct. Valproate is strictly contraindicated in women of childbearing potential unless conditions of the Pregnancy Prevention Programme are met due to 10% teratogenicity and 30-40% neurodevelopmental disorders.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bf2c2e2e-7108-48bc-a8ce-83ac2a346f9b', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'B', 'Dispense the full 3-month supply and advise patient to buy over-the-counter pregnancy test', 0, 'Sub-optimal and regulatory failure. Pharmacists must verify Annual Risk Acknowledgement form before dispensing.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9e96fa75-0903-4597-9ab0-b05abb4f1987', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'C', 'Switch patient immediately to Carbamazepine without specialist neurology consult', 0, 'Unsafe practice. Pharmacists cannot substitute anticonvulsants without specialist prescriber consultation due to status epilepticus risk.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3afb95ac-b666-4cbc-adb6-5a84f27e336c', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'D', 'Provide manufacturer patient leaflet only and dispense as routine', 0, 'Deprecated pre-2018 practice. Mandatory legal checks are now in place under MHRA regulations.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d8f3c292-450c-4871-993d-b5a63177bcb8', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'E', 'Supply in plain white dispensing bottle with original warning triangle discarded', 0, 'Illegal practice. Valproate must always be dispensed in original manufacturer packaging with visible pregnancy warning icon.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('421c4d4b-1896-444d-9af8-2c3a5b87216f', 'df964263-f2a3-4414-8263-cef0104dc5c4', 'Valproate must only be dispensed in original packaging to female patients with verified Pregnancy Prevention Programme compliance.', 'Teratogenic risks include neural tube defects, facial clefts, and severe autism spectrum disorders. Reference: MHRA Drug Safety Update: Valproate safety measures.', 'MHRA Drug Safety Update: Valproate safety measures', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('60386f25-6c90-4b95-bd2c-4e365dc158db', 'df964263-f2a3-4414-8263-cef0104dc5c4', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('6255bb50-9fdb-4e59-af18-f1fb7083b099', 'ACP-Q-0342', 1, 'published', 'p-mpharm', 'sub-depression', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('a947bd0b-43d9-4472-a69f-c702e0feb1ac', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'A 29-year-old male patient A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0342). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fd7c4588-b90b-4b6f-adc0-55d279b11519', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('36942a8c-ab3c-4ee5-98a0-9dbca7603755', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('32ee7969-0649-48a7-a588-16bf7439bcd2', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2fb9c23e-6153-4516-a713-c07514329739', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5fad94bf-550d-44f7-9809-ca07071574ab', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ec61eedb-117d-4335-8e92-fb5069f995c7', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('81a6b638-c4e6-48a2-8ca6-a22b32caa9dc', '6255bb50-9fdb-4e59-af18-f1fb7083b099', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
