INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6ad071af-21b1-44bb-ae03-b0b462ff1bc7', '4b4f72dd-8af6-4de2-ad62-24eadd8fdccc', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1ef5403e-7326-400d-8d9b-351c7dad6e6b', '4b4f72dd-8af6-4de2-ad62-24eadd8fdccc', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('25b76295-aeff-423e-bd90-375020e37ca7', '4b4f72dd-8af6-4de2-ad62-24eadd8fdccc', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('461aff46-10a4-4a8d-bb6a-0288b996369c', '4b4f72dd-8af6-4de2-ad62-24eadd8fdccc', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('d2fe17b5-d947-4ccf-aeb7-49ed55cf1d2c', '4b4f72dd-8af6-4de2-ad62-24eadd8fdccc', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
