INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('3c0442d2-376c-4453-af20-863463ee128b', '5318273e-8675-4d19-9cf6-c136baf25a3b', 'Valproate must only be dispensed in original packaging to female patients with verified Pregnancy Prevention Programme compliance.', 'Teratogenic risks include neural tube defects, facial clefts, and severe autism spectrum disorders. Reference: MHRA Drug Safety Update: Valproate safety measures.', 'MHRA Drug Safety Update: Valproate safety measures', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('d55b8d72-d0a6-4ab0-9bfb-113591b871e1', '5318273e-8675-4d19-9cf6-c136baf25a3b', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
