INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ceb6fc10-a8ee-4fb2-a6f4-8707054ca294', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'A 86-year-old male patient A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0378). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bc927be8-9413-44b9-b79c-de5f505be62c', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('83d65d69-3b60-4ae0-8b0e-9073256c5e36', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0a45bd60-4d80-419d-8760-f21bb5ebb0d0', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f02edadb-17cf-4beb-83c8-0edb06450ded', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('57516236-17f4-4e15-b14f-75015e498aa5', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('59dd352f-9c46-437c-959f-aba44fbdb083', 'a2d5399b-32bb-425c-b657-8635b95e1571', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
