INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('53c9b656-e9cb-4439-bb6b-77f87af735ce', '9fd1e7ae-92e6-4174-b7ac-695ebbc4563f', 'A 28-year-old female patient A 26-year-old female with generalised epilepsy attends community pharmacy for a repeat prescription of Sodium Valproate 500 mg tablets. She mentions she stopped using contraception two months ago. (Case Ref: CNS-0379). Relevant physiological and medication history have been reviewed.', 'What is the essential action for the pharmacist to take before dispensing this medication?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9d05012e-d0c0-4aaf-ba22-82f38979fe15', '9fd1e7ae-92e6-4174-b7ac-695ebbc4563f', 'A', 'Confirm active enrollment in the Valproate Pregnancy Prevention Programme (prevent) with signed Annual Risk Acknowledgement and immediate referral to prescriber', 1, 'Correct. Valproate is strictly contraindicated in women of childbearing potential unless conditions of the Pregnancy Prevention Programme are met due to 10% teratogenicity and 30-40% neurodevelopmental disorders.', 0, 1789655696);
