INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('998a1fde-a96b-4724-9880-28bb339b0dbd', '7d1591ca-1907-4176-a0b8-4a5b0311ecf5', 'C', 'Switch patient immediately to Carbamazepine without specialist neurology consult', 0, 'Unsafe practice. Pharmacists cannot substitute anticonvulsants without specialist prescriber consultation due to status epilepticus risk.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0c143c2c-43b7-4b95-a365-1d3558cfbc98', '7d1591ca-1907-4176-a0b8-4a5b0311ecf5', 'D', 'Provide manufacturer patient leaflet only and dispense as routine', 0, 'Deprecated pre-2018 practice. Mandatory legal checks are now in place under MHRA regulations.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dc91e4e0-e227-403c-b36b-b977fe88630c', '7d1591ca-1907-4176-a0b8-4a5b0311ecf5', 'E', 'Supply in plain white dispensing bottle with original warning triangle discarded', 0, 'Illegal practice. Valproate must always be dispensed in original manufacturer packaging with visible pregnancy warning icon.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('a79b8fd5-9e74-44c3-94d0-4f57b3137314', '7d1591ca-1907-4176-a0b8-4a5b0311ecf5', 'Valproate must only be dispensed in original packaging to female patients with verified Pregnancy Prevention Programme compliance.', 'Teratogenic risks include neural tube defects, facial clefts, and severe autism spectrum disorders. Reference: MHRA Drug Safety Update: Valproate safety measures.', 'MHRA Drug Safety Update: Valproate safety measures', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('8d882c27-521f-42d4-ad9f-97a22924cf44', '7d1591ca-1907-4176-a0b8-4a5b0311ecf5', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('f82be16e-c8d2-4043-bef7-79343f8c2848', 'ACP-Q-0384', 1, 'published', 'p-mpharm', 'sub-parkinson', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('9871bb0a-db29-4868-a662-5c64f93ad015', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'A 63-year-old male patient A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0384). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7aa1fb2e-407e-4a4f-b296-11b1156b8752', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4d224ef5-1a3d-4a35-8b30-949be51e4a12', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c67b2bbd-f801-4e78-abc1-3d6274fac7da', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('769d05ec-0808-41ac-a6aa-91abf803cba1', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1db6ac32-9a32-47cc-94a7-30bd41636678', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('d1b8a9e3-bdb6-45aa-bb7d-4a32cdbda814', 'f82be16e-c8d2-4043-bef7-79343f8c2848', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
