INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('edec2774-d789-4230-a336-2ba37a3c7387', '387114d7-be7b-4d06-b005-97b9ee69006f', 'B', 'Dispense the full 3-month supply and advise patient to buy over-the-counter pregnancy test', 0, 'Sub-optimal and regulatory failure. Pharmacists must verify Annual Risk Acknowledgement form before dispensing.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6e19e811-a35c-4a8c-84c6-c67d0a24a3f7', '387114d7-be7b-4d06-b005-97b9ee69006f', 'C', 'Switch patient immediately to Carbamazepine without specialist neurology consult', 0, 'Unsafe practice. Pharmacists cannot substitute anticonvulsants without specialist prescriber consultation due to status epilepticus risk.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2996b72a-f5f9-4609-9adc-682a49fdd7db', '387114d7-be7b-4d06-b005-97b9ee69006f', 'D', 'Provide manufacturer patient leaflet only and dispense as routine', 0, 'Deprecated pre-2018 practice. Mandatory legal checks are now in place under MHRA regulations.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('76685b69-7dd0-44e7-9ae9-ec16efa06a51', '387114d7-be7b-4d06-b005-97b9ee69006f', 'E', 'Supply in plain white dispensing bottle with original warning triangle discarded', 0, 'Illegal practice. Valproate must always be dispensed in original manufacturer packaging with visible pregnancy warning icon.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('49689324-d88f-4681-8371-2319cc514e47', '387114d7-be7b-4d06-b005-97b9ee69006f', 'Valproate must only be dispensed in original packaging to female patients with verified Pregnancy Prevention Programme compliance.', 'Teratogenic risks include neural tube defects, facial clefts, and severe autism spectrum disorders. Reference: MHRA Drug Safety Update: Valproate safety measures.', 'MHRA Drug Safety Update: Valproate safety measures', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('10ac6044-9ebe-49a5-abfb-a2465a68a20f', '387114d7-be7b-4d06-b005-97b9ee69006f', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('4f264217-59d7-4482-bf99-2cff3d3b1aec', 'ACP-Q-0446', 1, 'published', 'p-mpharm', 'sub-epilepsy', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('f33e1388-4ec1-4638-aaab-a4e268d670ae', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'A 42-year-old male patient A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0446). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d583a055-d038-4bdc-af09-80674d5e6b49', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('979c378a-5be6-4c14-82ad-f2f244c58819', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3517ad2c-e637-443b-94f5-9d4a8a04ec2a', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f55d0640-0c48-4488-842a-1f3ee066180f', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('01ce0a07-20df-4c56-a8dd-d9243041657d', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('633d1c36-2805-4c31-8b7d-878efae146ff', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('fc538a59-c0a1-4738-89b5-fc80e16add33', '4f264217-59d7-4482-bf99-2cff3d3b1aec', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
