INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('f4649124-5dc3-4b65-bbff-3b65a0cadb0b', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'A 66-year-old male patient A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0468). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1709d547-a46d-4f6c-a0a5-0b8ab725b6ca', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8fab4aa9-f680-4919-8893-30c53a6c7e08', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7b91de98-304f-4f4b-b2e0-bacdf1417680', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f82c9c23-d892-45b4-8586-8fcb23ecd45a', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f0ae0238-d3df-423b-9295-80d1b39ac45c', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('1bda3617-c766-4a93-ad28-7d18ea0f2ead', 'd1b0eef6-119e-4758-a1f5-310f803a405b', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
