INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'ACP-Q-0479', 1, 'published', 'p-mpharm', 'sub-parkinson', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ca9eaa53-2762-4a53-9140-9dc54e6935e7', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'A 78-year-old female patient A 26-year-old female with generalised epilepsy attends community pharmacy for a repeat prescription of Sodium Valproate 500 mg tablets. She mentions she stopped using contraception two months ago. (Case Ref: CNS-0479). Relevant physiological and medication history have been reviewed.', 'What is the essential action for the pharmacist to take before dispensing this medication?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7d248a95-00d9-4fa4-be06-ebfb23cd18f3', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'A', 'Confirm active enrollment in the Valproate Pregnancy Prevention Programme (prevent) with signed Annual Risk Acknowledgement and immediate referral to prescriber', 1, 'Correct. Valproate is strictly contraindicated in women of childbearing potential unless conditions of the Pregnancy Prevention Programme are met due to 10% teratogenicity and 30-40% neurodevelopmental disorders.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('024fa84c-0662-4740-9a89-8b42e7f7f2dd', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'B', 'Dispense the full 3-month supply and advise patient to buy over-the-counter pregnancy test', 0, 'Sub-optimal and regulatory failure. Pharmacists must verify Annual Risk Acknowledgement form before dispensing.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8d91675d-bc08-46b4-9c2d-bd4700b46c9e', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'C', 'Switch patient immediately to Carbamazepine without specialist neurology consult', 0, 'Unsafe practice. Pharmacists cannot substitute anticonvulsants without specialist prescriber consultation due to status epilepticus risk.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('42f109a2-230e-48c8-abbf-a2d50e6c4f67', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'D', 'Provide manufacturer patient leaflet only and dispense as routine', 0, 'Deprecated pre-2018 practice. Mandatory legal checks are now in place under MHRA regulations.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2be713f7-d2c9-4221-87ab-0623e0a9ceb6', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'E', 'Supply in plain white dispensing bottle with original warning triangle discarded', 0, 'Illegal practice. Valproate must always be dispensed in original manufacturer packaging with visible pregnancy warning icon.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('37962ce1-1796-4afa-94b9-13191bf596c7', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 'Valproate must only be dispensed in original packaging to female patients with verified Pregnancy Prevention Programme compliance.', 'Teratogenic risks include neural tube defects, facial clefts, and severe autism spectrum disorders. Reference: MHRA Drug Safety Update: Valproate safety measures.', 'MHRA Drug Safety Update: Valproate safety measures', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('0d1a2b16-780f-4044-a902-582c8d23bd8b', '65f1fd49-567c-45e0-b3bf-02ee6b3644cf', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('67ed66d7-6c85-4141-b7dc-962118917107', 'ACP-Q-0480', 1, 'published', 'p-mpharm', 'sub-substance', 'easy', 'sba', 'community', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ba85b7fa-bb04-4578-8322-27cb2cc687d2', '67ed66d7-6c85-4141-b7dc-962118917107', 'A 85-year-old male patient A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0480). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5857d85d-ee55-4c1a-a449-83d36ee4b460', '67ed66d7-6c85-4141-b7dc-962118917107', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cf98610f-341d-46a4-980a-8d8bf00b2ee8', '67ed66d7-6c85-4141-b7dc-962118917107', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8e039661-0716-4caf-ac0f-85085c48537a', '67ed66d7-6c85-4141-b7dc-962118917107', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9da4ebea-c05c-41f0-99d5-6635e1b6cd90', '67ed66d7-6c85-4141-b7dc-962118917107', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d2c1c242-1538-498f-9d14-11c6b4a7f115', '67ed66d7-6c85-4141-b7dc-962118917107', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('41e63200-798c-4362-9552-a3c36fe0a1e5', '67ed66d7-6c85-4141-b7dc-962118917107', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789655696, 1789655696);
