INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('de9f6203-ca5a-4cd9-8987-fc02f5ba1c52', '2bf29122-8a87-4d82-982d-c001a1de5184', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8701ce64-d1ff-4847-9001-2da388b3d259', '2bf29122-8a87-4d82-982d-c001a1de5184', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('13a46541-6489-46f6-b2e4-11bfa8a9a6ae', '2bf29122-8a87-4d82-982d-c001a1de5184', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789655696);
