INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('c1e11763-7764-4155-850c-99193918f30f', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'A 41-year-old female patient A 68-year-old non-pregnant female with lower urinary tract infection symptoms (dysuria, frequency, no fever or flank pain) has a documented eGFR of 32 mL/min. (Case Ref: INFECTIONS-0508). Relevant physiological and medication history have been reviewed.', 'Which empirical oral antimicrobial is most appropriate under UKHSA guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7336405f-92c8-4f08-85d5-dbcde5676bb1', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f30534f6-9a8d-4141-a152-81d84545b7fb', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5d980fc3-2bbe-4b22-b22f-f6686c07684c', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7b8c143d-6857-4bb6-be09-19edfd55eddd', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ce2eb31f-08a8-44cc-bcb2-0bd8455dec2d', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f4f310d7-6b25-4458-a993-adb46a237e04', 'e51c5b7d-bb91-4d65-a9cb-0a83bcf11251', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789655696, 1789655696);
