INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0421b93d-a0b2-4357-a0ab-4adad66ea8a7', 'c5e8e240-7369-45b6-bb3d-480089d3b34d', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789655696);
