INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('b204e90f-47d4-4c31-a54e-a501ec5eca5d', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'A 24-year-old female patient A 68-year-old non-pregnant female with lower urinary tract infection symptoms (dysuria, frequency, no fever or flank pain) has a documented eGFR of 32 mL/min. (Case Ref: INFECTIONS-0552). Relevant physiological and medication history have been reviewed.', 'Which empirical oral antimicrobial is most appropriate under UKHSA guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fdc95eb6-abd6-43eb-99e4-eb25dca0230b', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ef2194d5-83f6-4e89-8098-802a430a2229', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('01f126d9-e736-47bd-b2fc-5b2673a2eea0', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c3feb122-6b8d-4188-8e6f-a59992c6a1d1', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('db2708d8-654a-4d25-a61f-1d00ca1865c3', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('6ade7803-2157-40a0-b17b-393888ccbebd', 'c1dfc627-8f02-4593-8a18-9b19daaa520c', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789655696, 1789655696);
