INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('02eacd09-8592-482c-9ee7-c4ee49686040', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'A 55-year-old male patient A 64-year-old male receives once-daily IV Gentamicin (5 mg/kg) for severe Gram-negative sepsis. A serum concentration sampled 10 hours after the first infusion returns at 4.2 mg/L. (Case Ref: INFECTIONS-0575). Relevant physiological and medication history have been reviewed.', 'Using standard Hartford once-daily nomogram principles, what is the appropriate management decision?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('437131ee-ac78-4f92-91bb-d4c51c11a1a8', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'A', 'Extend dosing interval from 24 hours to 36 or 48 hours in accordance with nomogram plot', 1, 'Correct. A 10-hour level of 4.2 mg/L falls into the extended interval zone (36h or 48h). Extending interval allows trough levels to drop below 1 mg/L, preventing ototoxicity and nephrotoxicity.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5f3e3aa8-793d-4e2c-8a26-ddbc56622013', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'B', 'Administer the next scheduled 24-hour dose on time with reduced milligram amount', 0, 'Sub-optimal. Reducing dose compromises peak concentration (Cmax:MIC bactericidal efficacy); interval extension is the correct kinetic strategy.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e93c8280-6922-44cd-8be8-2f7355811d23', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'C', 'Double the dose to achieve faster bactericidal synergy', 0, 'Extremely dangerous. Causes catastrophic renal tubular necrosis and permanent vestibular/cochlear hair cell damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f65ca786-eaa3-4408-97e6-c0ffb383eabb', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'D', 'Switch to multiple-daily dosing (80 mg TDS) without trough monitoring', 0, 'Deprecated. Once-daily dosing provides equal efficacy with lower renal accumulation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6e6920e2-8280-400c-96b1-d6edbafd1192', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('4dc1cb5d-23d8-40bb-9f5a-4c064b1de921', 'c22069ff-9c3c-4f7f-a48a-65ce80522e56', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789655696, 1789655696);
