INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f6e630ad-af29-4a5b-8e1b-f72d5908e874', '2e9c4c0b-4ce6-43ea-81ee-ae70b3011a1d', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789655696);
