INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6c3a9925-a010-4835-a197-0aef86fcb3dc', 'cc68a5b0-1852-44a1-b9e3-b333bb18f09a', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('364c420f-0304-48c4-bbc7-2c4bc5387783', 'cc68a5b0-1852-44a1-b9e3-b333bb18f09a', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fec2624e-1e12-44cd-8355-a2919ac4ea1a', 'cc68a5b0-1852-44a1-b9e3-b333bb18f09a', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('730fefaf-3a40-4312-b19e-6329a25c24c9', 'cc68a5b0-1852-44a1-b9e3-b333bb18f09a', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('0ba67a5a-eb8e-45be-b78b-7b219068faee', 'cc68a5b0-1852-44a1-b9e3-b333bb18f09a', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('8efa14fb-4130-407f-ae6b-1d29be35e8b7', 'cc68a5b0-1852-44a1-b9e3-b333bb18f09a', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'ACP-Q-0637', 1, 'published', 'p-mpharm', 'sub-cap', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ab7e7673-54db-4d61-afe0-3ff847071c6f', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'A 34-year-old male patient A 64-year-old male receives once-daily IV Gentamicin (5 mg/kg) for severe Gram-negative sepsis. A serum concentration sampled 10 hours after the first infusion returns at 4.2 mg/L. (Case Ref: INFECTIONS-0637). Relevant physiological and medication history have been reviewed.', 'Using standard Hartford once-daily nomogram principles, what is the appropriate management decision?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a9c189b2-7f99-4d31-9e5f-76da845240ad', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'A', 'Extend dosing interval from 24 hours to 36 or 48 hours in accordance with nomogram plot', 1, 'Correct. A 10-hour level of 4.2 mg/L falls into the extended interval zone (36h or 48h). Extending interval allows trough levels to drop below 1 mg/L, preventing ototoxicity and nephrotoxicity.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c854c0d3-7683-44c0-b44f-311d4acf17be', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'B', 'Administer the next scheduled 24-hour dose on time with reduced milligram amount', 0, 'Sub-optimal. Reducing dose compromises peak concentration (Cmax:MIC bactericidal efficacy); interval extension is the correct kinetic strategy.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8c5fa4be-e033-42af-97a0-2259cf5eff77', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'C', 'Double the dose to achieve faster bactericidal synergy', 0, 'Extremely dangerous. Causes catastrophic renal tubular necrosis and permanent vestibular/cochlear hair cell damage.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e9bc972b-7ef4-4dd3-89ec-a7833825b797', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'D', 'Switch to multiple-daily dosing (80 mg TDS) without trough monitoring', 0, 'Deprecated. Once-daily dosing provides equal efficacy with lower renal accumulation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c443149e-b7e2-4b55-933c-f4e00547c2e4', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('bfd853e5-1541-41f7-87ad-593d97d71979', '3ad99f1a-66f7-4368-bfbd-911ea5d6cbee', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789655696, 1789655696);
