INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('2e0fa0f7-9356-4e3a-8750-27ed9286cd05', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'A 22-year-old female patient A 28-year-old adult with asthma using Beclometasone dipropionate 100 mcg twice daily reports using their Salbutamol inhaler 4 times a week, with night-time waking once weekly. Inhaler technique is confirmed satisfactory. (Case Ref: RESPIRATORY-0641). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate next step in pharmacological management according to BTS/SIGN guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c3bca759-de34-45aa-aecb-ed3874d305cc', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'A', 'Add an Inhaled Long-Acting Beta2 Agonist (LABA) in a fixed-dose combination inhaler with Low-Dose ICS', 1, 'Correct. For uncontrolled asthma on low-dose ICS, adding a LABA to ICS (often as maintenance and reliever therapy MART) is the primary evidence-based step before increasing ICS dose.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2f54d437-6eaf-48e6-9fb9-789573647c20', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'B', 'Increase Beclometasone monotherapy to 400 mcg twice daily without adding LABA', 0, 'Sub-optimal. Adding a LABA is more effective than doubling the steroid dose alone and causes fewer systemic steroid adverse effects.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2f8bd045-e575-493f-94b0-2e61e9c60992', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'C', 'Prescribe Salmeterol LABA as a standalone separate inhaler alongside SABA', 0, 'Dangerous and contraindicated. LABA monotherapy without adequate ICS is associated with severe asthma exacerbations and death (MHRA black box warning).', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a5e0c291-187b-4541-a401-33cac940bda7', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'D', 'Initiate oral Theophylline 200 mg twice daily', 0, 'Deprecated early-line choice. Theophylline has narrow therapeutic index and significant drug interactions.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d994aa76-33d9-47dd-9ae4-9b1fd2bda52f', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'E', 'Prescribe short course of Oral Prednisolone 40 mg daily without reviewing maintenance therapy', 0, 'Inappropriate for chronic sub-optimal control without severe acute exacerbation; addresses symptoms without fixing underlying baseline deficit.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e0f727a0-aad6-4851-8069-b2e44ab7418d', 'f2d63aa2-2b92-401b-a045-d88b93365911', 'Always pair LABA with ICS (preferably in a single combination device). Never use LABA monotherapy in asthma.', 'MART (Maintenance and Reliever Therapy) reduces oral corticosteroid courses and hospitalisations. Reference: BTS/SIGN British Guideline on the Management of Asthma & NICE NG80.', 'BTS/SIGN British Guideline on the Management of Asthma & NICE NG80', 1789655696, 1789655696);
