INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('04c95c49-982f-49d2-bd85-7d25a5a5bcb2', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'A 22-year-old female patient A 58-year-old patient with type 2 diabetes and a history of myocardial infarction 2 years ago has an HbA1c of 64 mmol/mol on Metformin 1 g twice daily. Current eGFR is 68 mL/min. (Case Ref: ENDOCRINE-0781). Relevant physiological and medication history have been reviewed.', 'Which agent should be introduced next according to NICE NG28?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8df28916-3fd0-464f-800d-b086a7e88add', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'A', 'Add an SGLT2 inhibitor with proven cardiovascular benefit (e.g. Empagliflozin 10 mg or Dapagliflozin 10 mg daily)', 1, 'Correct. For patients with T2DM and established CVD, NICE recommends introducing an SGLT2 inhibitor with proven cardiovascular benefit alongside metformin.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8d7b1675-8a03-47b5-8ec4-0fda72a5f23a', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'B', 'Add Gliclazide 40 mg once daily with breakfast', 0, 'Sub-optimal. Sulfonylureas improve glycaemia but lack cardiorenal protective outcome benefits and increase hypoglycaemia/weight gain risk.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c68b3b54-c593-4671-b4a6-1db94204781d', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'C', 'Add Pioglitazone 15 mg daily in a patient with NYHA Class III heart failure', 0, 'Strictly contraindicated. Pioglitazone causes fluid retention and precipitates or worsens heart failure.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('eab805be-2f56-4391-8e66-e438b3fafb59', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'D', 'Add Rosiglitazone', 0, 'Withdrawn from UK market due to increased ischaemic cardiac risk.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4062c960-4551-45f1-a27b-cb9ae21c7944', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'E', 'Start SGLT2 inhibitor without educating on Euglycaemic DKA and sick-day rules', 0, 'Dangerous failure. SGLT2i must be paused during acute illness, dehydration, or planned surgery to prevent diabetic ketoacidosis.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('3f1b9133-70e8-4e8a-9c3d-bb8ff5e4dc61', '1a05164a-4623-4abb-b9f5-ddac8867744d', 'Patients with T2DM and established CVD require early SGLT2 inhibitor therapy with cardiorenal protection.', 'Sick day rules for SGLT2 inhibitors: withhold during vomiting, diarrhoea, sepsis, or reduced oral intake. Reference: NICE NG28: Type 2 diabetes in adults (Section 1.3).', 'NICE NG28: Type 2 diabetes in adults (Section 1.3)', 1789655696, 1789655696);
