INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('d648ab8d-83e4-4413-ac34-96811a977f57', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'A 22-year-old female patient A private prescription for Morphine sulfate 10 mg tablets (Schedule 2 CD) is presented at a community pharmacy. The prescription is dated 32 days ago and specifies total quantity as 56 tablets without words and figures. (Case Ref: PHARMACY-LAW-0911). Relevant physiological and medication history have been reviewed.', 'Can the pharmacist legally dispense this prescription?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2273e6d1-3bfb-4f74-a8b1-d8d8c6dedb47', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'A', 'No, because Schedule 2 prescriptions are valid for only 28 days from date of signing and require total quantity in words and figures', 1, 'Correct. Schedule 2, 3, and 4 Controlled Drug prescriptions are legally valid for 28 days only. Schedule 2 and 3 prescriptions mandate total quantity in both words and figures.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6d2e9685-4e20-498a-810b-39f448a2d130', 'a4893b2e-8257-48d4-9570-e8dfcaccace7', 'B', 'Dispense half the quantity and request an amended prescription for the balance', 0, 'Illegal. An invalid CD prescription cannot be partially dispensed.', 1, 1789655696);
