INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('47133de0-904f-4983-9c8c-deb61fea081e', 'a3de3e16-3a31-4206-a5aa-8e5c9f2d8e76', 'E', 'Supply Penicillin V for 14 days', 0, 'NICE NG84 guidelines mandate a 5-day course for acute group A streptococcal pharyngitis.', 4, 1789655696);
