INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7b7ca5b6-0675-457f-8fb6-897214442650', '3059f35d-deee-428c-9c53-22d305dd0670', 'A', 'PPI twice daily + Amoxicillin 1 g twice daily + Clarithromycin 500 mg twice daily for 7 days', 1, 'Correct. Standard UK first-line triple eradication consists of a full-dose PPI bd + amoxicillin 1g bd + clarithromycin 500mg bd (or metronidazole 400mg bd) for 7 days.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f3dbcd46-518f-4a26-9c77-5cbe796da616', '3059f35d-deee-428c-9c53-22d305dd0670', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789655696);
