INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8b78d4fa-74ff-47ca-81ec-99ddc53ca567', 'b9826deb-e968-4cdf-9329-5d18296def90', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0f906778-5e92-4932-aecd-8fd9a2c23312', 'b9826deb-e968-4cdf-9329-5d18296def90', 'C', 'Prescribe Clarithromycin in a patient taking concurrent Simvastatin 40 mg', 0, 'Dangerous interaction. Strong CYP3A4 inhibition increases statin exposure exponentially, causing rhabdomyolysis.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bf4970b7-ba87-4b20-ab04-730c1152229b', 'b9826deb-e968-4cdf-9329-5d18296def90', 'D', 'Triple therapy containing Ranitidine instead of PPI', 0, 'Deprecated and unavailable; ranitidine was withdrawn globally due to NDMA impurities.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('377247c0-9757-4354-8f2b-b1f8487239ce', 'b9826deb-e968-4cdf-9329-5d18296def90', 'E', 'Retest H. pylori via stool antigen 2 days after completing antibiotics', 0, 'False-negative result. Wait at least 4 weeks post-antibiotics and 2 weeks post-PPI before retesting.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('3dd884fb-fc60-49b4-9167-51f6066505b2', 'b9826deb-e968-4cdf-9329-5d18296def90', 'H. pylori eradication requires 7 days of PPI bd + two antibiotics. Retest at least 4 weeks after treatment.', 'If penicillin allergic: PPI bd + Clarithromycin 250mg bd + Metronidazole 400mg bd. Reference: NICE NG184: Gastro-oesophageal reflux disease and dyspepsia.', 'NICE NG184: Gastro-oesophageal reflux disease and dyspepsia', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('3a6435fa-6bc8-4468-b32a-a61b77b6febf', 'b9826deb-e968-4cdf-9329-5d18296def90', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'ACP-Q-1231', 1, 'published', 'p-mpharm', 'sub-gout', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('fcdbeba8-cc6a-48f6-a7f5-14537a3a2f84', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'A 22-year-old female patient A 55-year-old male with recurrent gout attacks (3 flares in the last 6 months) has had his acute flare resolve. Serum urate is 480 micromol/L. eGFR is normal. (Case Ref: MUSCULOSKELETAL-1231). Relevant physiological and medication history have been reviewed.', 'What is the recommended approach for starting Urate Lowering Therapy (ULT)?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('97a2495c-29f4-43ec-a402-efc9b9ee1172', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'A', 'Initiate Allopurinol 100 mg daily with concurrent Colchicine 500 mcg od-bd as flare prophylaxis for up to 6 months; titrate monthly to urate < 300 micromol/L', 1, 'Correct. NICE NG219 recommends a treat-to-target strategy with target urate < 300 micromol/L. Prophylactic colchicine or NSAID prevents mobilization flares.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b9682bb8-3434-4775-9a00-827cdf556474', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'B', 'Start Allopurinol 300 mg daily without flare prophylaxis cover', 0, 'Sub-optimal. Rapid unbuffered drop in serum urate triggers acute crystal shedding and severe flare, leading to patient non-adherence.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3c1c132b-6eb9-4017-8162-5762b225bcb1', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'C', 'Prescribe Colchicine in a patient taking strong P-gp / CYP3A4 inhibitors (e.g. Clarithromycin) with severe renal failure', 0, 'Fatal toxicity risk. Severe neuro-myopathy and bone marrow suppression occur rapidly.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4d85fd96-981e-418c-bfe5-4cf5b67f50c2', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'D', 'Withhold allopurinol indefinitely until patient has at least 10 documented attacks', 0, 'Deprecated historic under-treatment; modern guidance encourages early ULT to prevent irreversible joint erosion and tophi.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e9134648-ac8f-477d-b14f-48b4e631c292', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'E', 'Check serum urate only once after 3 years without dose adjustment', 0, 'Fails treat-to-target principles. Monthly titration until urate < 300 micromol/L is mandatory.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('7f853db0-2ab2-42ce-bdac-af106afb69ce', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'Allopurinol treat-to-target urate is < 300 micromol/L. Always provide anti-flare cover during initiation.', 'HLA-B*5801 testing is considered in Han Chinese and Korean ancestry due to severe cutaneous adverse reaction (SCAR) risk. Reference: NICE NG219: Gout: diagnosis and management (Section 1.5).', 'NICE NG219: Gout: diagnosis and management (Section 1.5)', 1789655696, 1789655696);
