INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('ee68f760-7fe4-46fa-8ff9-642569918785', 'ACP-Q-1321', 1, 'published', 'p-mpharm', 'sub-eczema', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('123dbae1-0cf7-49e8-bad0-5eef40e1cc90', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'A 22-year-old female patient A mother asks for advice regarding her 4-year-old child who has a severe atopic eczema flare on the face and flexural folds. She has tubes of Clobetasol propionate, Betamethasone valerate, and Hydrocortisone 1%. (Case Ref: DERMATOLOGY-1321). Relevant physiological and medication history have been reviewed.', 'Which topical steroid is safe and appropriate for short-term application to the facial flare?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('97ba84e9-f236-412e-ac07-1068f26a5d02', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('411fb93d-ff1a-4179-9b48-65d2fff4f7fa', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ec4675b0-331b-4220-ac42-cace8e0632de', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('144f6906-239d-42c5-8892-5bab23a20c7a', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'D', 'Mix topical steroid 50:50 with liquid paraffin in the dispensing tub', 0, 'Deprecated historical practice. Diluting steroids leads to unpredictable stability and microbial contamination.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1bf352a3-d16e-4e9a-b283-4924340135f7', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'E', 'Apply emollient simultaneously without leaving a 20-30 minute interval', 0, 'Incorrect technique. Applying emollient at the exact same moment dilutes the active steroid and spreads it to unaffected skin.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('daf65f2b-f83f-4c67-bb8d-6f16a988a5c7', 'ee68f760-7fe4-46fa-8ff9-642569918785', 'Use mild corticosteroids (Hydrocortisone 1%) for face and flexures. Allow 20-30 minutes between steroid and emollient.', 'One Fingertip Unit (FTU) is approximately 0.5 g and covers the area of two adult palms. Reference: NICE CG57 & BNF Chapter 13.', 'NICE CG57 & BNF Chapter 13', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('4a919195-7592-49cd-b4e0-9bc0a3f76ed5', 'ee68f760-7fe4-46fa-8ff9-642569918785', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
