INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('db971186-edf5-47d3-a3db-8d6089f6b396', '405f9a03-63e9-40ee-bd77-1dc35f6d68f8', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4c091d86-6c45-4c7e-8f99-b5845951e9d7', '405f9a03-63e9-40ee-bd77-1dc35f6d68f8', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789655696);
