INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e1668b64-c332-48de-8c87-2865fd368f85', '5f4a9a73-9201-4915-a857-d65570bce765', 'Use mild corticosteroids (Hydrocortisone 1%) for face and flexures. Allow 20-30 minutes between steroid and emollient.', 'One Fingertip Unit (FTU) is approximately 0.5 g and covers the area of two adult palms. Reference: NICE CG57 & BNF Chapter 13.', 'NICE CG57 & BNF Chapter 13', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('0b7c19cf-9165-48cd-b566-41b7f5135f49', '5f4a9a73-9201-4915-a857-d65570bce765', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'ACP-Q-1406', 1, 'published', 'p-mpharm', 'sub-bph', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('0f2a7225-f034-4806-a571-87b9e06b335b', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'A 22-year-old female patient A 22-year-old female requests emergency contraception 80 hours after unprotected sexual intercourse. She takes Carbamazepine for focal seizures and has a BMI of 27. (Case Ref: GENITO-URINARY-1406). Relevant physiological and medication history have been reviewed.', 'What is the most effective and appropriate emergency contraceptive method?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2a06b7db-31f5-4e5c-bbf4-5e622c816ba3', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('30d0e3e9-8079-4408-82b3-eece031ff384', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ddeabc22-7613-4483-a3e6-1bad5397e302', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('44777bb9-d164-4ffe-80f6-cef0efe42570', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1ab8e865-d603-445a-809a-f00a15c42b4b', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('9b6b6beb-f39e-45b0-b46b-019154143530', 'e34feb0a-8321-46d5-88d4-e4f7c9054af8', 'Enzyme inducers require double-dose Levonorgestrel (3 mg) or Cu-IUD. Ulipristal is not recommended with enzyme inducers.', 'Cu-IUD is >99% effective and independent of body weight, BMI, or enzyme induction. Reference: FSRH Clinical Guideline: Emergency Contraception.', 'FSRH Clinical Guideline: Emergency Contraception', 1789655696, 1789655696);
