INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('468f43b9-3766-4a7c-a303-cb6f26529344', '7559077b-eefc-4f2f-833c-e924452e5fa4', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9469bc34-b962-4a60-b898-8569eb862112', '7559077b-eefc-4f2f-833c-e924452e5fa4', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('75b3d8a4-b1fd-4bb4-9ec6-7ffe3a669191', '7559077b-eefc-4f2f-833c-e924452e5fa4', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a6ff191f-fc20-4400-a06a-75650f008528', '7559077b-eefc-4f2f-833c-e924452e5fa4', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2251df9e-df09-46ae-8c3c-216869a37d21', '7559077b-eefc-4f2f-833c-e924452e5fa4', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ba9d2405-620d-41b3-a38b-8d11a3f2bb73', '7559077b-eefc-4f2f-833c-e924452e5fa4', 'Enzyme inducers require double-dose Levonorgestrel (3 mg) or Cu-IUD. Ulipristal is not recommended with enzyme inducers.', 'Cu-IUD is >99% effective and independent of body weight, BMI, or enzyme induction. Reference: FSRH Clinical Guideline: Emergency Contraception.', 'FSRH Clinical Guideline: Emergency Contraception', 1789655696, 1789655696);
