INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2565c9df-d687-4b5b-bf49-182e8b4cf750', 'be6ef5b8-c1f6-416e-aa05-34d46d1a945b', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cdf1f1a4-03bf-41e2-a20b-6e4d06c2e835', 'be6ef5b8-c1f6-416e-aa05-34d46d1a945b', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('58b8155d-319b-4835-ba38-a96ffaad6db2', 'be6ef5b8-c1f6-416e-aa05-34d46d1a945b', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2503c93f-e978-4eaa-b8fb-a5d3b12779f2', 'be6ef5b8-c1f6-416e-aa05-34d46d1a945b', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7409e2e2-b33a-4278-a6d4-f1bf2a8ea4c0', 'be6ef5b8-c1f6-416e-aa05-34d46d1a945b', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('8058f47e-5d7e-44cc-b724-0d7f7bbf2dfe', 'be6ef5b8-c1f6-416e-aa05-34d46d1a945b', 'Enzyme inducers require double-dose Levonorgestrel (3 mg) or Cu-IUD. Ulipristal is not recommended with enzyme inducers.', 'Cu-IUD is >99% effective and independent of body weight, BMI, or enzyme induction. Reference: FSRH Clinical Guideline: Emergency Contraception.', 'FSRH Clinical Guideline: Emergency Contraception', 1789655696, 1789655696);
