INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9e849457-42f8-4f1b-a5b8-ad0048508617', '4b4fa479-7e60-48f1-9ac2-48134255e8be', 'A', 'Copper Intrauterine Device (Cu-IUD) inserted within 5 days, OR double-dose Levonorgestrel (3 mg) if Cu-IUD declined', 1, 'Correct. The Cu-IUD is the most effective method up to 120 hours. For oral options: Ulipristal acetate is ineffective/contraindicated with enzyme inducers (Carbamazepine). Levonorgestrel dose must be doubled to 3 mg (two 1.5mg tablets) due to hepatic clearance induction.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6dc32c8f-f33d-47d9-b636-6b0ffbe32cd9', '4b4fa479-7e60-48f1-9ac2-48134255e8be', 'B', 'Ulipristal acetate (EllaOne) 30 mg single tablet', 0, 'Ineffective. Enzyme-inducing antiepileptics markedly reduce ulipristal plasma levels and its dose cannot be doubled.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('727e5158-da26-4868-8825-c150510e2bdf', '4b4fa479-7e60-48f1-9ac2-48134255e8be', 'C', 'Standard Levonorgestrel 1.5 mg single dose without adjustment for enzyme inducer', 0, 'Ineffective. Standard dose results in sub-therapeutic drug levels and high risk of unintended pregnancy.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d93b1305-2374-4222-9866-a64824de8a90', '4b4fa479-7e60-48f1-9ac2-48134255e8be', 'D', 'High-dose combined estrogen-progestogen (Yuzpe regimen)', 0, 'Withdrawn and deprecated due to severe nausea, emesis, and high failure rates.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('06eb5f61-82de-41b6-aa43-74ca5439f4de', '4b4fa479-7e60-48f1-9ac2-48134255e8be', 'E', 'Advise patient she is protected for future intercourse during the remainder of her cycle', 0, 'False and dangerous counselling. EHC provides no barrier or ongoing cycle protection; immediate ongoing contraception is required.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('49c4637b-87e2-46a1-8fda-d5a6393057fc', '4b4fa479-7e60-48f1-9ac2-48134255e8be', 'Enzyme inducers require double-dose Levonorgestrel (3 mg) or Cu-IUD. Ulipristal is not recommended with enzyme inducers.', 'Cu-IUD is >99% effective and independent of body weight, BMI, or enzyme induction. Reference: FSRH Clinical Guideline: Emergency Contraception.', 'FSRH Clinical Guideline: Emergency Contraception', 1789655696, 1789655696);
