INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('2917e077-fd73-47e5-8cf4-40c32bf25e54', 'ACP-Q-1486', 1, 'published', 'p-mpharm', 'sub-oral-chemo', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('a182a8cf-6800-449b-bee1-c87a75924204', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'A 22-year-old female patient A 50-year-old patient undergoing systemic cytotoxic chemotherapy for breast cancer attends community pharmacy with a temperature of 38.3°C and shivering, but feels otherwise relatively well. (Case Ref: MALIGNANCY-1486). Relevant physiological and medication history have been reviewed.', 'What is the immediate and mandatory course of action?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('123391af-312c-44b6-8fe2-e144943a3cd0', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'A', 'Direct the patient immediately to the emergency oncology assessment unit or hospital A&E for urgent IV broad-spectrum antibiotics within 1 hour', 1, 'Correct. Febrile neutropenia is a medical emergency with mortality risk from septic shock. Empirical IV antibiotics (e.g. piperacillin-tazobactam) must be administered within 60 minutes of arrival.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('267f1b81-f74d-44ea-9759-3efdac35c12b', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('30820cdb-99f3-4dec-931f-99702d86700d', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cfabe1e7-8112-4c1f-b520-f939cb4f01ef', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'D', 'Wait for blood culture and full blood count results before initiating antimicrobial therapy', 0, 'Deprecated historical practice. "Door-to-needle" time must be < 1 hour without waiting for lab confirmation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3d9d48a3-6b7c-44f4-ae3b-14712789ebea', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'E', 'Reassure patient that mild fever is expected after chemotherapy', 0, 'Extremely negligent. Any fever >= 38.0°C in a chemotherapy patient within 4 weeks of treatment must be treated as neutropenic sepsis until proven otherwise.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('740c5229-7d0a-4ca2-bab3-9af2eef1f116', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('b877e042-1db5-4e8d-b283-3ad6910c28b5', '2917e077-fd73-47e5-8cf4-40c32bf25e54', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
