INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e1844ee7-33a2-4a0e-8f78-cb152e943757', '2d52e9fd-4d41-4673-9ecc-d55f16e2db31', 'A', 'Direct the patient immediately to the emergency oncology assessment unit or hospital A&E for urgent IV broad-spectrum antibiotics within 1 hour', 1, 'Correct. Febrile neutropenia is a medical emergency with mortality risk from septic shock. Empirical IV antibiotics (e.g. piperacillin-tazobactam) must be administered within 60 minutes of arrival.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('43c97b5a-fc45-48fd-b092-ccf036df3049', '2d52e9fd-4d41-4673-9ecc-d55f16e2db31', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
