INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bc048078-18d8-461c-afcf-6f14486ca0a0', 'f8921767-3075-47cb-ae36-e519894f134d', 'A', 'Direct the patient immediately to the emergency oncology assessment unit or hospital A&E for urgent IV broad-spectrum antibiotics within 1 hour', 1, 'Correct. Febrile neutropenia is a medical emergency with mortality risk from septic shock. Empirical IV antibiotics (e.g. piperacillin-tazobactam) must be administered within 60 minutes of arrival.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('06bd3009-11ae-48a6-b15b-26ab826bada7', 'f8921767-3075-47cb-ae36-e519894f134d', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1c051c51-5021-40d8-bb12-13c55e6d9659', 'f8921767-3075-47cb-ae36-e519894f134d', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('72dc06b9-4d64-40ff-8b88-2dcf3d614744', 'f8921767-3075-47cb-ae36-e519894f134d', 'D', 'Wait for blood culture and full blood count results before initiating antimicrobial therapy', 0, 'Deprecated historical practice. "Door-to-needle" time must be < 1 hour without waiting for lab confirmation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('226920ee-2636-4f19-b951-30205e8e93a0', 'f8921767-3075-47cb-ae36-e519894f134d', 'E', 'Reassure patient that mild fever is expected after chemotherapy', 0, 'Extremely negligent. Any fever >= 38.0°C in a chemotherapy patient within 4 weeks of treatment must be treated as neutropenic sepsis until proven otherwise.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f92a0ef8-7695-47d3-951b-a2b30ebeeaed', 'f8921767-3075-47cb-ae36-e519894f134d', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
