INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('6ebb9a90-11ff-464d-a0a3-51ec09fe1198', '9972b97c-a25b-4b9d-8e31-dbcb2761ca7d', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('cd14dfd9-6f8f-4d54-961d-4eefdd0edcad', '9972b97c-a25b-4b9d-8e31-dbcb2761ca7d', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'ACP-Q-1560', 1, 'published', 'p-mpharm', 'sub-chemo-emesis', 'medium', 'sba', 'hospital', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('7ee08f04-a357-4fb0-b6c2-6f26c6422025', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'A 85-year-old female patient A 50-year-old patient undergoing systemic cytotoxic chemotherapy for breast cancer attends community pharmacy with a temperature of 38.3°C and shivering, but feels otherwise relatively well. (Case Ref: MALIGNANCY-1560). Relevant physiological and medication history have been reviewed.', 'What is the immediate and mandatory course of action?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('86f6733a-8955-439e-95d5-ab2a401a47ac', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'A', 'Direct the patient immediately to the emergency oncology assessment unit or hospital A&E for urgent IV broad-spectrum antibiotics within 1 hour', 1, 'Correct. Febrile neutropenia is a medical emergency with mortality risk from septic shock. Empirical IV antibiotics (e.g. piperacillin-tazobactam) must be administered within 60 minutes of arrival.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fb572733-a652-4539-b757-736987cb2504', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'B', 'Dispense OTC Paracetamol 1 g and advise to contact GP if fever persists for 48 hours', 0, 'Fatal mistake. Antipyretics mask fevers and delaying antibiotic treatment leads to rapidly fatal bacterial sepsis.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cc483181-3504-4db4-8038-1aba3ce5dfff', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'C', 'Supply Oral Amoxicillin 500 mg and advise bed rest', 0, 'Inadequate and life-threatening. Oral amoxicillin does not cover Pseudomonas aeruginosa or hospital-acquired bacteremia.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('76e7887c-2905-4eef-be5e-8a7c4a891504', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'D', 'Wait for blood culture and full blood count results before initiating antimicrobial therapy', 0, 'Deprecated historical practice. "Door-to-needle" time must be < 1 hour without waiting for lab confirmation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('02c8b24e-fe6e-4a1b-b064-0c870cba7562', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'E', 'Reassure patient that mild fever is expected after chemotherapy', 0, 'Extremely negligent. Any fever >= 38.0°C in a chemotherapy patient within 4 weeks of treatment must be treated as neutropenic sepsis until proven otherwise.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('a7ea9928-480f-4de9-bf49-4a8b447365e0', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 'Chemotherapy fever >= 38°C is an emergency. Urgent hospital referral for IV antibiotics within 1 hour is life-saving.', 'Defined as neutrophil count <= 0.5 x 10^9/L with fever >= 38°C or clinical sepsis. Reference: NICE CG151: Neutropenic sepsis: prevention and management.', 'NICE CG151: Neutropenic sepsis: prevention and management', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('879b85f2-09dd-4c40-9e88-70d5545b346f', 'db6fd6f3-ef33-43b2-b47a-5de17ebc05d8', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('3b106a30-69ee-4230-85e6-b02c36b7668c', 'ACP-Q-1561', 1, 'published', 'p-mpharm', 'sub-anaemia', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('cd2d469d-a615-4e6e-8249-d8bdf5854370', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'A 22-year-old female patient A 35-year-old female with microcytic hypochromic anaemia is prescribed Ferrous sulfate 200 mg tablets (65 mg elemental iron). She complains of severe constipation and nausea when taking it three times daily. (Case Ref: BLOOD-NUTRITION-1561). Relevant physiological and medication history have been reviewed.', 'What evidence-based modification improves tolerance and maintains iron absorption?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('12997125-1cbc-433b-8ddb-a87ff32365ea', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5d1ef2b9-729b-47d6-a512-2ce7e6bdede3', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('df3045d0-b023-4663-a086-b10bf215f5c4', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ad765723-6fc1-4d85-9332-2b979c3a88fd', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('de9558e2-44f3-4737-b1cc-0a4033126606', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e6726154-6dd2-4ed1-ad3e-7dd6f94902c6', '3b106a30-69ee-4230-85e6-b02c36b7668c', 'Alternate-day or once-daily oral iron improves absorption and GI tolerance. Avoid modified-release iron preparations.', 'Target rise in haemoglobin is approximately 2 g/100 mL every 3 to 4 weeks. Reference: BNF Section 9.1.1 & British Society of Gastroenterology.', 'BNF Section 9.1.1 & British Society of Gastroenterology', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('4c7e80e5-b853-46e3-8f9c-25f218010cfe', '3b106a30-69ee-4230-85e6-b02c36b7668c', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
