INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('57c8ce71-7c2b-425a-bc08-6e12a7226a12', '3e97feb4-e2dc-4a35-94d5-9ab7a27fc74d', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('63476aee-555c-4f3b-8ce2-6fb2a04a2090', '3e97feb4-e2dc-4a35-94d5-9ab7a27fc74d', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789655696);
