INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('31e19a4a-91bf-4a60-87aa-ec2e5817a70c', '22c8a61f-646e-456b-95ae-f0c39d5f88d7', 'A 22-year-old female patient A 32-year-old female at 16 weeks gestation is diagnosed with gestational hypertension (BP 154/98 mmHg). Proteinuria is negative. Past medical history is unremarkable. (Case Ref: OBSTETRICS-GYNAECOLOGY-1636). Relevant physiological and medication history have been reviewed.', 'Which antihypertensive medication is recommended first-line by NICE NG133?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2f1aa222-af52-4e42-a951-ba812ffaf5ad', '22c8a61f-646e-456b-95ae-f0c39d5f88d7', 'A', 'Labetalol orally (or modified-release Nifedipine if labetalol is contraindicated/asthmatic)', 1, 'Correct. Labetalol is first-line for gestational hypertension. Nifedipine is second-line (or first-line if asthmatic). Methyldopa is third-line.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d9168800-5e29-41cb-b4b7-82dbb5c06f46', '22c8a61f-646e-456b-95ae-f0c39d5f88d7', 'B', 'Methyldopa 250 mg twice daily as initial choice', 0, 'Sub-optimal compared to labetalol due to maternal sedation, depression risk, and postural hypotension.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f57cf804-65ba-4799-b4cc-612840d38a79', '22c8a61f-646e-456b-95ae-f0c39d5f88d7', 'C', 'Ramipril 5 mg once daily', 0, 'Strictly contraindicated. ACE inhibitors and ARBs cause severe fetopathy, oligohydramnios, skull hypoplasia, and neonatal renal failure.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('45860303-af31-4173-b7b6-e6e4261be808', '22c8a61f-646e-456b-95ae-f0c39d5f88d7', 'D', 'Atenolol 50 mg daily', 0, 'Deprecated in pregnancy due to association with fetal intrauterine growth restriction (IUGR).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0a8b6c1d-3355-4049-809f-cd3993f51294', '22c8a61f-646e-456b-95ae-f0c39d5f88d7', 'E', 'Withhold all treatment until blood pressure exceeds 180/120 mmHg', 0, 'Dangerous inaction. Failure to treat severe hypertension increases placental abruption and maternal stroke risks.', 4, 1789655696);
