INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('484b39a6-fdaa-4c32-8c56-91ea1f80cb13', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 'A', 'Labetalol orally (or modified-release Nifedipine if labetalol is contraindicated/asthmatic)', 1, 'Correct. Labetalol is first-line for gestational hypertension. Nifedipine is second-line (or first-line if asthmatic). Methyldopa is third-line.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b4881bb0-9dff-4fac-8360-6e6ff0fe4bf1', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 'B', 'Methyldopa 250 mg twice daily as initial choice', 0, 'Sub-optimal compared to labetalol due to maternal sedation, depression risk, and postural hypotension.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e780e583-ec2c-4f86-914d-af02511ae9f7', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 'C', 'Ramipril 5 mg once daily', 0, 'Strictly contraindicated. ACE inhibitors and ARBs cause severe fetopathy, oligohydramnios, skull hypoplasia, and neonatal renal failure.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1b5e1f55-0e56-4093-bc5a-c55047e52dfd', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 'D', 'Atenolol 50 mg daily', 0, 'Deprecated in pregnancy due to association with fetal intrauterine growth restriction (IUGR).', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bb8ec3e4-f396-4dd0-a36e-fc8c77302de3', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 'E', 'Withhold all treatment until blood pressure exceeds 180/120 mmHg', 0, 'Dangerous inaction. Failure to treat severe hypertension increases placental abruption and maternal stroke risks.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('522dc2f1-6dae-40d0-be9a-1445e7f40e60', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 'Labetalol is first-line for pregnancy hypertension. ACE inhibitors and ARBs are strictly contraindicated in pregnancy.', 'Target blood pressure in pregnancy is 135/85 mmHg. Reference: NICE NG133: Hypertension in pregnancy: diagnosis and management.', 'NICE NG133: Hypertension in pregnancy: diagnosis and management', 1789655696, 1789655696);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('0000ecf3-3596-47c8-9146-5e5fe3932370', '5d0f4c08-7473-4152-a5fc-fccb498f5ad8', 1789655696, 1789655696, 1789655696, 1789655696, 0, 1789655696, 1789655696);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'ACP-Q-1701', 1, 'published', 'p-mpharm', 'sub-otitis-externa', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('1653a598-466b-45e1-8790-5a61d4410d52', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'A 22-year-old female patient A 42-year-old swimmer presents with left ear pain, discharge, and itch. Examination suggests localized otitis externa, but the tympanic membrane cannot be fully visualized and perforation cannot be ruled out. (Case Ref: ENT-1701). Relevant physiological and medication history have been reviewed.', 'Which ear drop preparation is safe to prescribe when tympanic perforation cannot be excluded?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('565f48f8-0969-4b6d-aecb-fa39791b4161', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'A', 'Ciprofloxacin 0.2% ear drops (non-aminoglycoside preparation)', 1, 'Correct. Aminoglycoside-containing drops (gentamicin, neomycin, framycetin) are contraindicated when the eardrum is perforated due to risk of permanent sensorineural hearing loss. Ciprofloxacin drops are non-ototoxic.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e120db67-93f4-459a-b14e-5c1a7c273b86', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'B', 'Gentisone HC (Gentamicin with Hydrocortisone) ear drops', 0, 'Contraindicated and dangerous. Aminoglycoside inner ear toxicity causes permanent deafness.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d834366b-0b19-4cfe-abfa-cc6efbbc2987', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'C', 'Neomycin and dexamethasone spray into middle ear cavity', 0, 'Contraindicated. High risk of ototoxicity if entering through perforation.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5a1a6bdb-0bdf-46b0-afb9-e98d2f142323', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'D', 'Syringe ear vigorously with warm tap water to clear purulent discharge', 0, 'Dangerous and contraindicated in potential perforation.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3985c328-43e2-4a50-8eb1-43b2ca788934', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'E', 'Advise patient to insert cotton wool soaked in pure olive oil for 3 weeks without review', 0, 'Inappropriate and promotes bacterial growth in moist enclosed environment.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('0733fe74-f0c4-4a09-a73f-5c18c5a9755b', '0761a792-fdc2-41a7-a04c-ef19e381fcd2', 'Never use aminoglycoside ear drops (gentamicin, neomycin) if the eardrum is or may be perforated.', 'Topical treatment for 7 to 14 days is standard for uncomplicated otitis externa. Reference: NICE CKS: Otitis externa & BNF Section 12.1.1.', 'NICE CKS: Otitis externa & BNF Section 12.1.1', 1789655696, 1789655696);
