INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('73296736-2541-4f2c-b2bb-d6614ec8009d', '741cc095-4853-40e3-a0f6-4ad521604558', 'A 22-year-old female patient A 66-year-old male with newly diagnosed open-angle glaucoma has a documented medical history of severe brittle asthma with frequent exacerbations. (Case Ref: OPHTHALMOLOGY-1761). Relevant physiological and medication history have been reviewed.', 'Which first-line ocular pressure-lowering drop is most appropriate?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6dbb612c-7edf-4936-9f24-4c3a748beb79', '741cc095-4853-40e3-a0f6-4ad521604558', 'A', 'Latanoprost 50 mcg/mL eye drops once daily at night (prostaglandin analogue)', 1, 'Correct. Prostaglandin analogues are first-line for primary open-angle glaucoma and do not cause bronchospasm. Beta-blocker drops (timolol, betaxolol) are contraindicated in asthma.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('971e66ee-be7c-431b-9641-42073e3a64db', '741cc095-4853-40e3-a0f6-4ad521604558', 'B', 'Timolol 0.5% eye drops twice daily', 0, 'Strictly contraindicated. Systemic absorption of ocular beta-blockers via the nasolacrimal duct triggers life-threatening bronchospasm.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('391cc734-be88-41b1-9ad3-84eff017bc1d', '741cc095-4853-40e3-a0f6-4ad521604558', 'C', 'Betaxolol 0.5% eye drops in patient with uncontrolled bronchospasm', 0, 'Unsafe. Even "cardioselective" beta-blocker drops can precipitate severe asthma attacks in sensitive individuals.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2409ca99-ed18-4ffc-8c39-37ec3b8e4aba', '741cc095-4853-40e3-a0f6-4ad521604558', 'D', 'Pilocarpine 2% drops four times daily as first-line maintenance', 0, 'Deprecated as first-line due to intense miosis, brow ache, and blurred vision.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('004c044d-04c9-444d-8be6-ce7021bad61f', '741cc095-4853-40e3-a0f6-4ad521604558', 'E', 'Administer drops without educating on nasolacrimal occlusion (punctal pressure)', 0, 'Poor administration technique. Nasolacrimal pressure for 1-2 minutes reduces systemic drug absorption by up to 60%.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('a94fd75d-f964-48a9-b695-65489cc45900', '741cc095-4853-40e3-a0f6-4ad521604558', 'Ocular beta-blockers (Timolol) are contraindicated in asthma. Prostaglandin analogues (Latanoprost) are first-line.', 'Latanoprost counselling: irreversible brown iris darkening, eyelash lengthening, and peri-orbital fat atrophy. Reference: NICE NG81: Glaucoma: diagnosis and management.', 'NICE NG81: Glaucoma: diagnosis and management', 1789655696, 1789655696);
