INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('22dcaf38-ed86-49d5-9bd9-818310959ff3', 'fd00e00f-7afa-4085-a36b-fc9bfb5d85d5', 'B', 'Lidocaine 2% with Adrenaline 1:80,000 solution', 0, 'Contraindicated and dangerous for digital ring block due to end-arteriole vasospasm.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ba6d7e80-553f-4ad5-8cb8-cd57d4381d28', 'fd00e00f-7afa-4085-a36b-fc9bfb5d85d5', 'C', 'Bupivacaine 0.5% with Adrenaline 1:200,000 for rapid local digital infiltration', 0, 'Strictly contraindicated for end-artery infiltration.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7448a340-f10b-4e47-a2ae-50800840ed61', 'fd00e00f-7afa-4085-a36b-fc9bfb5d85d5', 'D', 'Cocaine hydrochloride topical paste', 0, 'Deprecated toxic practice for peripheral skin suturing.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e1bba145-3f37-422d-a91c-8c948ca65ad1', 'fd00e00f-7afa-4085-a36b-fc9bfb5d85d5', 'E', 'Inject exceeding maximum plain lidocaine safe limit of 3 mg/kg (or 200 mg total)', 0, 'Dose violation leading to central nervous system and cardiovascular toxicity.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('24e40d1c-a86b-44c6-9513-6f241ac7f060', 'fd00e00f-7afa-4085-a36b-fc9bfb5d85d5', 'Never use adrenaline-containing local anaesthetics in areas with end-artery circulation (digits, ear, nose, penis).', 'Intralipid (20% lipid emulsion) is the specific rescue agent for systemic local anaesthetic toxicity (LAST). Reference: BNF Section 15.2 & Resuscitation Council UK.', 'BNF Section 15.2 & Resuscitation Council UK', 1789655696, 1789655696);
