INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('134aaf8a-14da-4783-973c-b70e302bcea4', 'ACP-Q-1866', 1, 'published', 'p-mpharm', 'sub-paracetamol-tox', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('3690ae44-d64f-4a71-bcb3-2491aee5c9d7', '134aaf8a-14da-4783-973c-b70e302bcea4', 'A 22-year-old female patient A 24-year-old patient reports ingesting 20 g of paracetamol in divided doses over the past 14 hours ("staggered overdose"). Baseline blood tests show normal ALT and normal creatinine. (Case Ref: POISONING-EMERGENCY-1866). Relevant physiological and medication history have been reviewed.', 'What is the mandatory clinical treatment decision regarding Acetylcysteine?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9b9fadbe-5051-4b7b-b97c-a8558b1974ff', '134aaf8a-14da-4783-973c-b70e302bcea4', 'A', 'Initiate IV Acetylcysteine immediately without waiting for serum paracetamol levels or nomogram plotting', 1, 'Correct. In staggered paracetamol overdoses (taken over > 1 hour), the paracetamol treatment nomogram CANNOT be used. Acetylcysteine must be commenced immediately regardless of the serum paracetamol concentration.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('89e064e5-5976-4079-8b6a-d60e6618fa57', '134aaf8a-14da-4783-973c-b70e302bcea4', 'B', 'Wait for the 4-hour serum paracetamol level and plot on the single-ingestion nomogram curve', 0, 'Fatal error. The nomogram is validated ONLY for acute single ingestions within 4-15 hours. Staggered overdoses render the nomogram uninterpretable.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a230740d-ceff-459f-9078-6265e2a3c444', '134aaf8a-14da-4783-973c-b70e302bcea4', 'C', 'Administer Oral Activated Charcoal 50 g at 14 hours post-ingestion', 0, 'Ineffective and contraindicated. Activated charcoal is only effective within 1 hour of ingestion and impairs oral antidotes.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('41b8d2d1-68b4-4930-9d0f-9ea4ceea8dd4', '134aaf8a-14da-4783-973c-b70e302bcea4', 'D', 'Withhold acetylcysteine because baseline transaminases (ALT) are currently normal', 0, 'Fatal error. ALT rises 24-48 hours after ingestion; waiting for hepatotoxicity before treating causes irreversible liver failure.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f482fed4-a2f2-401c-a93f-54aae1aa879d', '134aaf8a-14da-4783-973c-b70e302bcea4', 'E', 'Stop acetylcysteine infusion immediately if mild flush develops without anaphylactoid assessment', 0, 'Incorrect management. Common non-IgE mediated reactions can be managed by pausing infusion, giving antihistamine, and restarting at slower rate.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('fae7a252-7835-4f59-be0b-beab66a2164e', '134aaf8a-14da-4783-973c-b70e302bcea4', 'Never use the paracetamol nomogram for staggered overdoses. Start Acetylcysteine immediately.', 'Snap 12-hour or simplified 2-bag IV acetylcysteine regimens reduce adverse hypersensitivity reactions. Reference: TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose.', 'TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose', 1789655696, 1789655696);
